css:
:root{
  --porcelain:#F8F4ED; --merlot:#5A2B38; --merlot-d:#421E28; --merlot-l:#7A4353;
  --taupe:#C8B9AA; --taupe-l:#E7DED2; --taupe-xl:#F1EBE1;
  --ink:#20201F; --muted:#6E6862; --line:#DED4C7; --white:#FFFDFA;
  --blush:#E9D9D2; --sage:#A3AE98;
  --gut:44px; --r:3px;
  --shadow:0 1px 2px rgba(32,32,31,.04), 0 12px 34px rgba(32,32,31,.07);
  --shadow-lg:0 2px 6px rgba(32,32,31,.05), 0 26px 64px rgba(32,32,31,.12);
  --serif:"EB Garamond",Georgia,"Times New Roman",serif;
  --sans:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0;background:var(--porcelain);color:var(--ink);font-family:var(--sans);
  font-size:16.5px;line-height:1.7;-webkit-font-smoothing:antialiased}
h1,h2,h3,h4{font-family:var(--serif);font-weight:400;line-height:1.14;letter-spacing:-.005em;margin:0}
p{margin:0}
a{color:inherit;text-decoration:none}
img{max-width:100%}
ul,ol{margin:0;padding:0;list-style:none}

.wrap{width:100%;max-width:1280px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.sec{padding-top:104px;padding-bottom:104px}
.sec-t{padding-top:76px;padding-bottom:76px}
.eyebrow{font-family:var(--sans);font-weight:500;font-size:11.5px;letter-spacing:.22em;
  text-transform:uppercase;color:var(--muted);margin-bottom:18px}
.h2{font-size:clamp(30px,3.9vw,47px)}
.h3{font-size:clamp(24px,2.6vw,32px)}
.lead{color:var(--muted);font-size:17.5px;max-width:60ch;line-height:1.75}
.ctr{text-align:center}
.ctr .lead{margin-left:auto;margin-right:auto}
.sec-head{margin-bottom:46px}
.rule{height:1px;background:var(--line);border:0;margin:0}
em.acc{font-style:italic;color:var(--merlot)}

/* ---------- images ---------- */
.cimg{display:block;width:100%;height:auto;aspect-ratio:4/3;object-fit:cover;background:var(--taupe-l)}
.simg{display:block;width:100%;height:auto;aspect-ratio:3/4;object-fit:cover;background:var(--taupe-l)}
.wimg{display:block;width:100%;height:auto;aspect-ratio:5/2;object-fit:cover;background:var(--taupe-l)}

/* ---------- reveal (pure CSS, JS-free) ---------- */
.rv{animation:rvIn .9s both}
.rv2{animation-delay:.09s}.rv3{animation-delay:.18s}.rv4{animation-delay:.27s}
@keyframes rvIn{from{opacity:.55;transform:translateY(24px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.rv{animation:none}}

/* ---------- buttons ---------- */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;
  font-family:var(--sans);font-weight:500;font-size:12.5px;letter-spacing:.16em;text-transform:uppercase;
  padding:17px 34px;border-radius:var(--r);border:1px solid transparent;cursor:pointer;
  transition:background .22s ease, color .22s ease, border-color .22s ease;white-space:nowrap}
.btn-1{background:var(--merlot);color:#fff}
.btn-1:hover{background:var(--merlot-d)}
.btn-2{background:transparent;color:var(--ink);border-color:var(--taupe)}
.btn-2:hover{background:var(--taupe-xl);border-color:var(--merlot)}
.btn-w{background:#fff;color:var(--merlot);border-color:#fff}
.btn-w:hover{background:var(--taupe-xl)}
.btn-o{background:transparent;color:#fff;border-color:rgba(255,255,255,.5)}
.btn-o:hover{background:rgba(255,255,255,.12);border-color:#fff}
.btn-sm{padding:12px 24px;font-size:11px}
.btn-lg{padding:19px 42px;font-size:13px}
.lnk{font-family:var(--sans);font-size:11.5px;letter-spacing:.16em;text-transform:uppercase;
  font-weight:500;color:var(--merlot);display:inline-flex;align-items:center;gap:9px}
.lnk::after{content:"";width:22px;height:1px;background:var(--merlot);transition:width .22s ease}
a:hover .lnk::after,.lnk:hover::after{width:34px}

/* ---------- header ---------- */
header{position:sticky;top:0;z-index:60;background:rgba(248,244,237,.95);
  backdrop-filter:saturate(150%) blur(12px);border-bottom:1px solid var(--line)}
.hdr{display:flex;align-items:center;gap:26px;min-height:84px}
.brand{flex-shrink:0;font-family:var(--serif);font-size:25px;letter-spacing:.02em;color:var(--ink);
  white-space:nowrap;line-height:1}
.brand span{font-style:italic}
.nav{margin-left:auto;display:flex;align-items:center;gap:2px}
.nav>li{position:relative}
.nav a.top,.nav .drop-lbl{display:flex;align-items:center;gap:6px;padding:10px 13px;
  font-size:12.5px;letter-spacing:.11em;text-transform:uppercase;font-weight:500;color:var(--ink);
  cursor:pointer;white-space:nowrap;transition:color .2s ease}
.nav a.top:hover,.nav .drop-lbl:hover{color:var(--merlot)}
.nav-cta{display:none}
.nav .caret{width:8px;height:8px;flex-shrink:0;opacity:.6}
.menu{position:absolute;top:calc(100% + 14px);left:-8px;min-width:268px;background:var(--white);
  border:1px solid var(--line);box-shadow:var(--shadow-lg);padding:16px 12px;
  opacity:0;visibility:hidden;transform:translateY(8px);transition:.2s ease}
.nav>li:hover>.menu,.nav>li:focus-within>.menu{opacity:1;visibility:visible;transform:none}
.menu a{display:block;padding:9px 14px;font-size:14.5px;font-family:var(--serif);color:var(--ink);
  transition:color .18s ease,background .18s ease}
.menu a:hover{background:var(--taupe-xl);color:var(--merlot)}
.menu .mh{display:block;padding:4px 14px 10px;font-size:10.5px;letter-spacing:.2em;
  text-transform:uppercase;color:var(--muted);font-family:var(--sans);font-weight:500}
.hdr-act{display:flex;align-items:center;gap:14px;flex-shrink:0}
.burger,.mtoggle,.dtoggle{display:none}

/* ---------- hero ---------- */
.hero{position:relative;overflow:hidden;background:var(--taupe-l)}
.hero-bg{position:absolute;inset:0;z-index:0}
.hero-bg img{width:100%;height:100%;object-fit:cover;object-position:62% 42%}
.hero-scrim{position:absolute;inset:0;z-index:1;pointer-events:none;
  background:linear-gradient(96deg,rgba(32,32,31,.82) 0%,rgba(32,32,31,.68) 30%,
    rgba(32,32,31,.30) 54%,rgba(32,32,31,.06) 76%,rgba(32,32,31,0) 100%)}
.hero-grid{position:relative;z-index:2;display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr);
  gap:60px;align-items:center;padding-top:118px;padding-bottom:118px}
.hero-txt{color:#fff;min-width:0}
.hero-txt .eyebrow{color:rgba(255,255,255,.78)}
h1{font-size:clamp(38px,5.2vw,66px);color:#fff;margin-bottom:24px;line-height:1.08}
h1 em{font-style:italic;color:var(--blush)}
.hero-lead{font-size:18px;color:rgba(255,255,255,.86);max-width:50ch;margin-bottom:34px;line-height:1.75}
.ticks{display:flex;flex-wrap:wrap;gap:12px 30px;margin-top:30px}
.tick{display:flex;align-items:center;gap:10px;font-size:13px;color:rgba(255,255,255,.82);
  letter-spacing:.03em}
.tick svg{width:15px;height:15px;flex-shrink:0}
.swap-tag{position:absolute;right:16px;bottom:16px;z-index:3;background:rgba(32,32,31,.6);
  color:#fff;font-size:10.5px;letter-spacing:.12em;text-transform:uppercase;padding:7px 15px;border-radius:var(--r)}

/* ---------- quick-start card (hero) ---------- */
.qs{background:var(--white);border:1px solid var(--line);box-shadow:var(--shadow-lg);
  padding:36px 34px;min-width:0}
.qs h2{font-size:26px;margin-bottom:8px}
.qs .qs-s{font-size:14.5px;color:var(--muted);margin-bottom:24px;line-height:1.6}
.qs form{display:grid;gap:16px;min-width:0}
.field{min-width:0}
.field>label{display:block;font-size:10.5px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;
  color:var(--muted);margin-bottom:8px}
input,select,textarea{min-width:0;width:100%;border:1px solid var(--line);border-radius:var(--r);
  padding:14px 15px;font-size:15px;font-family:var(--sans);color:var(--ink);background:var(--porcelain);
  appearance:none;transition:border-color .2s ease, box-shadow .2s ease}
input:focus,select:focus,textarea:focus{outline:none;border-color:var(--merlot);
  box-shadow:0 0 0 3px rgba(90,43,56,.12)}
select{background-image:linear-gradient(45deg,transparent 50%,var(--muted) 50%),
  linear-gradient(135deg,var(--muted) 50%,transparent 50%);
  background-position:calc(100% - 20px) 21px, calc(100% - 14px) 21px;
  background-size:6px 6px, 6px 6px;background-repeat:no-repeat;padding-right:42px}
textarea{resize:vertical;min-height:104px;line-height:1.6}
textarea::placeholder,input::placeholder{color:#9C948C;font-size:14px}
.frow{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px}
.frow>*{min-width:0}
.qs .btn,.enq .btn[type=submit]{width:100%}
.fnote{font-size:11.5px;color:var(--muted);line-height:1.6;text-align:center}
.opt-lbl{font-size:9.5px;letter-spacing:.12em;color:var(--merlot);background:var(--taupe-xl);
  padding:3px 9px;border-radius:var(--r);margin-left:8px}

/* ---------- 4-step form (pure CSS, no JS) ---------- */
.qs-head{margin-bottom:26px;padding-bottom:22px;border-bottom:1px solid var(--line)}
.qs-head h2{font-size:30px;margin-bottom:8px}
.stp{position:absolute;opacity:0;pointer-events:none;width:0;height:0}
.hp{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.stepper{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px;margin-bottom:28px}
.stepper label{display:flex;align-items:center;gap:9px;min-width:0;cursor:pointer;
  padding-top:13px;border-top:2px solid var(--line);transition:border-color .25s ease}
.stepper b{font-family:var(--serif);font-weight:400;font-size:13px;color:var(--muted);flex-shrink:0;
  transition:color .25s ease}
.stepper span{font-size:11px;letter-spacing:.11em;text-transform:uppercase;color:var(--muted);
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;transition:color .25s ease}
.pane{display:none;gap:18px}
#st1:checked ~ .panes .p1,#st2:checked ~ .panes .p2,
#st3:checked ~ .panes .p3,#st4:checked ~ .panes .p4{display:grid}
#st1:checked ~ .stepper label:nth-child(1),#st2:checked ~ .stepper label:nth-child(2),
#st3:checked ~ .stepper label:nth-child(3),#st4:checked ~ .stepper label:nth-child(4){border-top-color:var(--merlot)}
#st1:checked ~ .stepper label:nth-child(1) b,#st1:checked ~ .stepper label:nth-child(1) span,
#st2:checked ~ .stepper label:nth-child(2) b,#st2:checked ~ .stepper label:nth-child(2) span,
#st3:checked ~ .stepper label:nth-child(3) b,#st3:checked ~ .stepper label:nth-child(3) span,
#st4:checked ~ .stepper label:nth-child(4) b,#st4:checked ~ .stepper label:nth-child(4) span{color:var(--merlot)}
.nextb{cursor:pointer}
.btnrow{display:flex;gap:12px;flex-wrap:wrap}
.btnrow>*{flex:1 1 0;min-width:0}
.btnrow .btn-2{flex:0 0 auto;padding-left:26px;padding-right:26px}
.picks.tight label{padding:8px 15px;font-size:12.5px}
.consent{display:flex;gap:12px;align-items:flex-start;font-size:13.2px;color:var(--muted);
  line-height:1.6;cursor:pointer;min-width:0}
.consent input{width:17px;height:17px;flex-shrink:0;margin-top:3px;accent-color:var(--merlot);appearance:auto}
.mem-in{border-top:1px solid var(--line);padding-top:14px;margin-top:2px}
input[type=file]{padding:11px 14px;font-size:13.5px;background:var(--porcelain)}

/* ---------- assurance band ---------- */
.assure-band{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);gap:0;
  background:var(--white);border:1px solid var(--line)}
.assure-txt{padding:52px 50px;min-width:0}
.assure-txt .lead{margin-bottom:32px}
.assure-img{min-width:0}
.assure-img img{display:block;width:100%;height:100%;min-height:420px;object-fit:cover}

/* ---------- trust strip ---------- */
.strip{background:var(--ink);color:#E7E2DB}
.strip .wrap{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:26px;
  padding-top:30px;padding-bottom:30px}
.strip div{min-width:0;display:flex;align-items:center;gap:13px;font-size:13.2px;letter-spacing:.04em}
.strip svg{width:19px;height:19px;flex-shrink:0}

/* ---------- style / card tiles ---------- */
.tiles{display:grid;gap:26px}
.t6{grid-template-columns:repeat(6,minmax(0,1fr));gap:18px}
.t4{grid-template-columns:repeat(4,minmax(0,1fr))}
.t3{grid-template-columns:repeat(3,minmax(0,1fr))}
.t2{grid-template-columns:repeat(2,minmax(0,1fr))}
.tile{min-width:0;display:block;background:transparent}
.tile img{margin-bottom:16px;transition:opacity .3s ease}
.tile:hover img{opacity:.86}
.tile b{display:block;font-family:var(--serif);font-weight:400;font-size:20px;margin-bottom:6px}
.tile span{display:block;font-size:13.8px;color:var(--muted);line-height:1.6}
.tile .lnk{margin-top:13px}
.t6 .tile b{font-size:16.5px}
.t6 .tile span{font-size:12.6px}

/* ---------- bordered cards ---------- */
.card{min-width:0;display:flex;flex-direction:column;background:var(--white);
  border:1px solid var(--line);transition:border-color .25s ease, box-shadow .25s ease}
.card:hover{border-color:var(--taupe);box-shadow:var(--shadow)}
.card .cb{padding:28px 30px 30px;display:flex;flex-direction:column;flex:1}
.card h3{font-size:22px;margin-bottom:10px}
.card p{font-size:14.8px;color:var(--muted);line-height:1.7}
.card .lnk{margin-top:auto;padding-top:20px}
.kwl{margin-top:14px;font-size:12.6px;color:var(--muted);line-height:1.7}
.kwl b{color:var(--ink);font-weight:500}

/* ---------- how it works ---------- */
.steps{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0;
  border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.step{min-width:0;padding:46px 40px;border-right:1px solid var(--line)}
.step:last-child{border-right:0}
.step .n{font-family:var(--serif);font-size:15px;letter-spacing:.2em;color:var(--merlot);
  display:block;margin-bottom:20px}
.step h3{font-size:24px;margin-bottom:12px}
.step p{font-size:14.8px;color:var(--muted);line-height:1.7}

/* ---------- enquiry section ---------- */
.enq{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(0,.75fr);gap:0;
  background:var(--white);border:1px solid var(--line)}
.enq-main{padding:52px 50px;min-width:0}
.enq-main h2{margin-bottom:10px}
.enq-main>.lead{margin-bottom:32px;font-size:16px}
.enq form{display:grid;gap:18px;min-width:0}
.picks{display:flex;flex-wrap:wrap;gap:9px}
.picks label{display:inline-flex;align-items:center;font-size:13px;padding:9px 17px;
  border:1px solid var(--line);border-radius:var(--r);background:var(--porcelain);cursor:pointer;
  transition:background .18s ease, border-color .18s ease}
.picks input{position:absolute;opacity:0;width:0;height:0}
.picks label:hover{border-color:var(--taupe)}
.picks label:has(input:checked){background:var(--merlot);border-color:var(--merlot);color:#fff}
.enq-side{background:var(--taupe-xl);padding:52px 40px;min-width:0;border-left:1px solid var(--line)}
.enq-side h3{font-size:24px;margin-bottom:10px}
.enq-side>p{font-size:14.5px;color:var(--muted);line-height:1.7;margin-bottom:28px}
.assure{display:grid;gap:22px;margin-bottom:30px}
.assure div{display:flex;gap:14px;min-width:0}
.assure svg{width:20px;height:20px;flex-shrink:0;margin-top:3px}
.assure b{display:block;font-family:var(--serif);font-weight:400;font-size:17.5px;margin-bottom:3px}
.assure span{font-size:13.5px;color:var(--muted);line-height:1.65}
.privacy{border-top:1px solid var(--line);padding-top:22px;font-size:13px;color:var(--muted);line-height:1.7}
.privacy b{display:block;font-family:var(--serif);font-size:16px;color:var(--ink);margin-bottom:6px;font-weight:400}
.mem{display:flex;align-items:center;gap:18px;background:var(--taupe-xl);border:1px solid var(--line);
  border-top:0;padding:22px 30px;font-size:13.5px;color:var(--muted);line-height:1.65;min-width:0}
.mem svg{width:26px;height:26px;flex-shrink:0}
.mem b{color:var(--ink);font-weight:500}

/* ---------- real weddings ---------- */
.rw .tile img{aspect-ratio:4/5}
.rw-meta{font-size:10.5px;letter-spacing:.2em;text-transform:uppercase;color:var(--muted);
  display:block;margin-bottom:7px}

/* ---------- pricing feature ---------- */
.price-f{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);align-items:stretch;
  background:var(--merlot);color:#fff}
.price-img{min-width:0}
.price-img img{display:block;width:100%;height:100%;min-height:400px;object-fit:cover}
.price-txt{padding:60px 56px;min-width:0;display:flex;flex-direction:column;justify-content:center}
.price-txt .eyebrow{color:rgba(255,255,255,.62)}
.price-txt h2{color:#fff;margin-bottom:18px}
.price-txt>p{color:rgba(255,255,255,.82);font-size:16.5px;line-height:1.75;margin-bottom:28px}
.bands{display:grid;gap:0;margin-bottom:32px;border-top:1px solid rgba(255,255,255,.22)}
.bands div{display:flex;justify-content:space-between;gap:20px;padding:15px 0;
  border-bottom:1px solid rgba(255,255,255,.22);font-size:14.8px;min-width:0}
.bands span:first-child{color:rgba(255,255,255,.85)}
.bands span:last-child{font-family:var(--serif);font-size:17px;white-space:nowrap}
.price-note{font-size:12.5px;color:rgba(255,255,255,.6);margin-top:-16px;margin-bottom:26px}

/* ---------- locations ---------- */
.loc-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:36px}
.loc-col{min-width:0}
.loc-col h3{font-size:21px;margin-bottom:4px}
.loc-col .st{font-size:10.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--muted);
  display:block;margin-bottom:16px}
.loc-col li{border-bottom:1px solid var(--line)}
.loc-col a{display:block;font-size:14.6px;padding:9px 0;color:var(--ink);overflow-wrap:anywhere;
  transition:color .18s ease,padding .18s ease}
.loc-col a:hover{color:var(--merlot);padding-left:6px}
.pop{display:flex;flex-wrap:wrap;gap:10px;margin-top:18px}
.pop a{border:1px solid var(--line);padding:9px 19px;font-size:13.2px;background:var(--white);
  transition:.18s ease;border-radius:var(--r)}
.pop a:hover{border-color:var(--merlot);color:var(--merlot)}

/* ---------- faq ---------- */
.faq{max-width:900px;margin:0 auto;border-top:1px solid var(--line)}
.faq details{border-bottom:1px solid var(--line)}
.faq summary{cursor:pointer;list-style:none;padding:26px 58px 26px 0;position:relative;
  font-family:var(--serif);font-size:21px;color:var(--ink);transition:color .2s ease}
.faq summary:hover{color:var(--merlot)}
.faq summary::-webkit-details-marker{display:none}
.faq summary::after,.faq summary::before{content:"";position:absolute;right:12px;top:37px;
  background:var(--merlot);transition:transform .25s ease, opacity .25s ease}
.faq summary::after{width:15px;height:1px}
.faq summary::before{width:1px;height:15px;right:19px;top:30px}
.faq details[open] summary::before{opacity:0;transform:rotate(90deg)}
.faq .ans{padding:0 60px 28px 0;font-size:15.6px;color:var(--muted);line-height:1.8}

/* ---------- final CTA ---------- */
.band{position:relative;overflow:hidden;background:var(--merlot);color:#fff}
.band-img{position:absolute;inset:0;z-index:1}
.band-img img{width:100%;height:100%;object-fit:cover;opacity:.24}
.band-in{position:relative;z-index:2;padding:96px 44px;text-align:center}
.band h2{color:#fff;font-size:clamp(30px,4.2vw,52px);margin-bottom:18px}
.band h2 em{font-style:italic;color:var(--blush)}
.band p{color:rgba(255,255,255,.84);font-size:17.5px;max-width:52ch;margin:0 auto 36px}
.cta-row{display:flex;flex-wrap:wrap;gap:16px;justify-content:center}

/* ---------- footer ---------- */
footer{background:var(--ink);color:#A9A29A;padding-top:84px}
.f-top{display:grid;grid-template-columns:minmax(0,1.5fr) repeat(4,minmax(0,1fr));gap:40px;
  padding-bottom:56px;border-bottom:1px solid rgba(255,255,255,.13)}
.f-brand{min-width:0}
.f-brand .brand{color:#fff;display:inline-block;margin-bottom:18px}
.f-brand p{font-size:14.2px;line-height:1.75;max-width:32ch;margin-bottom:24px}
.f-col{min-width:0}
.f-col h3{font-family:var(--sans);font-weight:500;font-size:10.5px;letter-spacing:.2em;
  text-transform:uppercase;color:#fff;margin-bottom:18px}
.f-col li{margin-bottom:11px}
.f-col a{font-size:14px;overflow-wrap:anywhere;transition:color .18s ease}
.f-col a:hover{color:var(--blush)}
.f-bot{display:flex;flex-wrap:wrap;gap:16px 30px;align-items:center;justify-content:space-between;
  padding:28px 0 36px;font-size:12.8px;color:#7C766F}
.f-bot a:hover{color:var(--blush)}
.credit{display:inline-flex;align-items:center;gap:9px;white-space:nowrap}
.credit img{width:22px;height:22px;border-radius:5px;flex-shrink:0;display:block}

/* ---------- sticky mobile bar ---------- */
.sticky{display:none}

/* ---------- thank-you ---------- */
.ty{max-width:720px;margin:0 auto;text-align:center}
.ty-mark{width:78px;height:78px;border:1px solid var(--taupe);border-radius:50%;display:grid;
  place-items:center;margin:0 auto 30px}
.ty-mark svg{width:34px;height:34px}
.ty h1{color:var(--ink);font-size:clamp(34px,4.6vw,52px);margin-bottom:20px}
.ty>.lead{margin:0 auto 40px}
.ty-next{border-top:1px solid var(--line);text-align:left;margin-bottom:40px}
.ty-next li{display:flex;gap:22px;padding:26px 0;border-bottom:1px solid var(--line);min-width:0}
.ty-next b{font-family:var(--serif);font-size:15px;letter-spacing:.16em;color:var(--merlot);flex-shrink:0}
.ty-next span{display:block;min-width:0}
.ty-next strong{display:block;font-family:var(--serif);font-weight:400;font-size:20px;
  color:var(--ink);margin-bottom:5px}
.ty-next em{font-style:normal;font-size:14.8px;color:var(--muted);line-height:1.7}
.note{margin-top:36px;font-size:12.5px;color:var(--muted);border:1px dashed var(--taupe);
  padding:16px 22px;line-height:1.7}

/* ================= responsive ================= */
@media (max-width:1560px){ .nav a.top,.nav .drop-lbl{padding:10px 9px;font-size:11.4px;letter-spacing:.08em}
  .hdr{gap:18px} .brand{font-size:23px} }
@media (max-width:1400px){
  .burger{display:grid;place-items:center;width:46px;height:46px;border:1px solid var(--line);
    background:var(--white);cursor:pointer;margin-left:auto;flex-shrink:0;border-radius:var(--r)}
  .burger span{display:block;width:20px;height:1px;background:var(--ink);position:relative}
  .burger span::before,.burger span::after{content:"";position:absolute;left:0;width:20px;height:1px;background:var(--ink)}
  .burger span::before{top:-6px}.burger span::after{top:6px}
  .hdr-act{display:none}
  .nav{position:fixed;top:84px;left:0;right:0;bottom:0;margin:0;background:var(--porcelain);
    display:block;overflow-y:auto;padding:22px var(--gut) 48px;
    clip-path:inset(0 0 0 100%);pointer-events:none;opacity:0;
    transition:clip-path .34s ease, opacity .28s ease;z-index:70}
  .mtoggle:checked ~ .nav{clip-path:inset(0 0 0 0);pointer-events:auto;opacity:1}
  .nav>li{border-bottom:1px solid var(--line)}
  .nav a.top,.nav .drop-lbl{padding:18px 2px;font-size:13px;letter-spacing:.14em;justify-content:space-between}
  .nav .caret{width:11px;height:11px;transition:transform .22s ease}
  .menu{position:static;opacity:1;visibility:visible;transform:none;box-shadow:none;border:0;
    padding:0 0 16px;min-width:0;max-height:0;overflow:hidden;transition:max-height .34s ease;background:transparent}
  .dtoggle:checked + .drop-lbl + .menu{max-height:900px}
  .dtoggle:checked + .drop-lbl .caret{transform:rotate(180deg)}
  .menu a{padding:9px 0;font-size:16px;color:var(--muted)}
  .menu .mh{padding-left:0}
  .nav-cta{display:flex!important;flex-direction:column;gap:12px;padding-top:26px;border:0!important}
  .nav-cta .btn{width:100%}
}
@media (max-width:1100px){
  .hero-grid{grid-template-columns:minmax(0,1fr);gap:46px;padding-top:76px;padding-bottom:76px}
  .hero-scrim{background:linear-gradient(180deg,rgba(32,32,31,.60) 0%,rgba(32,32,31,.70) 40%,rgba(32,32,31,.78) 100%)}
  .hero-bg img{object-position:50% 38%}
  .qs{max-width:580px}
  .swap-tag{display:none}
  .t6{grid-template-columns:repeat(3,minmax(0,1fr))}
  .t4,.t3,.t2{grid-template-columns:repeat(2,minmax(0,1fr))}
  .steps{grid-template-columns:minmax(0,1fr)}
  .step{border-right:0;border-bottom:1px solid var(--line);padding:36px 0}
  .step:last-child{border-bottom:0}
  .enq,.price-f,.assure-band{grid-template-columns:minmax(0,1fr)}
  .enq-main{padding:40px 32px}
  .enq-side{border-left:0;border-top:1px solid var(--line);padding:40px 32px}
  .assure-txt{padding:40px 32px}
  .assure-img{order:-1}
  .assure-img img{min-height:260px}
  .qs{max-width:none}
  .price-img img{min-height:280px}
  .price-txt{padding:44px 34px}
  .loc-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:30px}
  .strip .wrap{grid-template-columns:repeat(2,minmax(0,1fr))}
  .f-top{grid-template-columns:repeat(3,minmax(0,1fr))}
  .f-brand{grid-column:1/-1}
}
@media (max-width:768px){
  :root{--gut:26px}
  .sec{padding-top:70px;padding-bottom:70px}
  .sec-t{padding-top:54px;padding-bottom:54px}
  .nav{top:74px}
  .hdr{min-height:74px}
  .brand{font-size:22px}
  .band-in{padding:64px 24px}
  .qs{padding:28px 24px}
  .stepper{grid-template-columns:repeat(4,minmax(0,1fr));gap:4px}
  .stepper span{display:none}
  .stepper label{justify-content:center;padding-top:11px}
  .stepper b{font-size:12px}
  .sticky{display:flex;position:fixed;left:0;right:0;bottom:0;z-index:80;gap:11px;
    background:rgba(248,244,237,.97);backdrop-filter:blur(12px);border-top:1px solid var(--line);
    padding:11px 16px calc(11px + env(safe-area-inset-bottom))}
  .sticky .btn{flex:1 1 0;min-width:0;padding:15px 10px;font-size:11px;letter-spacing:.1em}
  footer{padding-bottom:82px}
}
@media (max-width:620px){
  .t6,.t4,.t3,.t2,.loc-grid,.f-top{grid-template-columns:minmax(0,1fr)}
  .strip .wrap{grid-template-columns:minmax(0,1fr);gap:16px}
  .frow{grid-template-columns:minmax(0,1fr)}
  .f-top{gap:30px}
  .rw .tile img{aspect-ratio:4/3}
}
@media (max-width:430px){
  :root{--gut:20px}
  .enq-main,.enq-side,.price-txt,.assure-txt{padding:32px 22px}
  .btnrow{flex-direction:column}
  .btnrow>*{width:100%}
  .card .cb{padding:24px 22px 26px}
  .cta-row .btn{width:100%}
  .btn{white-space:normal;text-align:center;padding-left:20px;padding-right:20px;max-width:100%}
  .faq summary{font-size:19px;padding-right:44px}
}

:root{
  --porcelain:#F8F4ED; --merlot:#5A2B38; --merlot-d:#421E28; --merlot-l:#7A4353;
  --taupe:#C8B9AA; --taupe-l:#E7DED2; --taupe-xl:#F1EBE1;
  --ink:#20201F; --muted:#6E6862; --line:#DED4C7; --white:#FFFDFA;
  --blush:#E9D9D2; --sage:#A3AE98;
  --gut:44px; --r:3px;
  --shadow:0 1px 2px rgba(32,32,31,.04), 0 12px 34px rgba(32,32,31,.07);
  --shadow-lg:0 2px 6px rgba(32,32,31,.05), 0 26px 64px rgba(32,32,31,.12);
  --serif:"EB Garamond",Georgia,"Times New Roman",serif;
  --sans:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0;background:var(--porcelain);color:var(--ink);font-family:var(--sans);
  font-size:16.5px;line-height:1.7;-webkit-font-smoothing:antialiased}
h1,h2,h3,h4{font-family:var(--serif);font-weight:400;line-height:1.14;letter-spacing:-.005em;margin:0}
p{margin:0}
a{color:inherit;text-decoration:none}
img{max-width:100%}
ul,ol{margin:0;padding:0;list-style:none}

.wrap{width:100%;max-width:1280px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.sec{padding-top:104px;padding-bottom:104px}
.sec-t{padding-top:76px;padding-bottom:76px}
.eyebrow{font-family:var(--sans);font-weight:500;font-size:11.5px;letter-spacing:.22em;
  text-transform:uppercase;color:var(--muted);margin-bottom:18px}
.h2{font-size:clamp(30px,3.9vw,47px)}
.h3{font-size:clamp(24px,2.6vw,32px)}
.lead{color:var(--muted);font-size:17.5px;max-width:60ch;line-height:1.75}
.ctr{text-align:center}
.ctr .lead{margin-left:auto;margin-right:auto}
.sec-head{margin-bottom:46px}
.rule{height:1px;background:var(--line);border:0;margin:0}
em.acc{font-style:italic;color:var(--merlot)}

/* ---------- images ---------- */
.cimg{display:block;width:100%;height:auto;aspect-ratio:4/3;object-fit:cover;background:var(--taupe-l)}
.simg{display:block;width:100%;height:auto;aspect-ratio:3/4;object-fit:cover;background:var(--taupe-l)}
.wimg{display:block;width:100%;height:auto;aspect-ratio:5/2;object-fit:cover;background:var(--taupe-l)}

/* ---------- reveal (pure CSS, JS-free) ---------- */
.rv{animation:rvIn .9s both}
.rv2{animation-delay:.09s}.rv3{animation-delay:.18s}.rv4{animation-delay:.27s}
@keyframes rvIn{from{opacity:.55;transform:translateY(24px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.rv{animation:none}}

/* ---------- buttons ---------- */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;
  font-family:var(--sans);font-weight:500;font-size:12.5px;letter-spacing:.16em;text-transform:uppercase;
  padding:17px 34px;border-radius:var(--r);border:1px solid transparent;cursor:pointer;
  transition:background .22s ease, color .22s ease, border-color .22s ease;white-space:nowrap}
.btn-1{background:var(--merlot);color:#fff}
.btn-1:hover{background:var(--merlot-d)}
.btn-2{background:transparent;color:var(--ink);border-color:var(--taupe)}
.btn-2:hover{background:var(--taupe-xl);border-color:var(--merlot)}
.btn-w{background:#fff;color:var(--merlot);border-color:#fff}
.btn-w:hover{background:var(--taupe-xl)}
.btn-o{background:transparent;color:#fff;border-color:rgba(255,255,255,.5)}
.btn-o:hover{background:rgba(255,255,255,.12);border-color:#fff}
.btn-sm{padding:12px 24px;font-size:11px}
.btn-lg{padding:19px 42px;font-size:13px}
.lnk{font-family:var(--sans);font-size:11.5px;letter-spacing:.16em;text-transform:uppercase;
  font-weight:500;color:var(--merlot);display:inline-flex;align-items:center;gap:9px}
.lnk::after{content:"";width:22px;height:1px;background:var(--merlot);transition:width .22s ease}
a:hover .lnk::after,.lnk:hover::after{width:34px}

/* ---------- header ---------- */
header{position:sticky;top:0;z-index:60;background:rgba(248,244,237,.95);
  backdrop-filter:saturate(150%) blur(12px);border-bottom:1px solid var(--line)}
.hdr{display:flex;align-items:center;gap:26px;min-height:84px}
.brand{flex-shrink:0;font-family:var(--serif);font-size:25px;letter-spacing:.02em;color:var(--ink);
  white-space:nowrap;line-height:1}
.brand span{font-style:italic}
.nav{margin-left:auto;display:flex;align-items:center;gap:2px}
.nav>li{position:relative}
.nav a.top,.nav .drop-lbl{display:flex;align-items:center;gap:6px;padding:10px 13px;
  font-size:12.5px;letter-spacing:.11em;text-transform:uppercase;font-weight:500;color:var(--ink);
  cursor:pointer;white-space:nowrap;transition:color .2s ease}
.nav a.top:hover,.nav .drop-lbl:hover{color:var(--merlot)}
.nav-cta{display:none}
.nav .caret{width:8px;height:8px;flex-shrink:0;opacity:.6}
.menu{position:absolute;top:calc(100% + 14px);left:-8px;min-width:268px;background:var(--white);
  border:1px solid var(--line);box-shadow:var(--shadow-lg);padding:16px 12px;
  opacity:0;visibility:hidden;transform:translateY(8px);transition:.2s ease}
.nav>li:hover>.menu,.nav>li:focus-within>.menu{opacity:1;visibility:visible;transform:none}
.menu a{display:block;padding:9px 14px;font-size:14.5px;font-family:var(--serif);color:var(--ink);
  transition:color .18s ease,background .18s ease}
.menu a:hover{background:var(--taupe-xl);color:var(--merlot)}
.menu .mh{display:block;padding:4px 14px 10px;font-size:10.5px;letter-spacing:.2em;
  text-transform:uppercase;color:var(--muted);font-family:var(--sans);font-weight:500}
.hdr-act{display:flex;align-items:center;gap:14px;flex-shrink:0}
.burger,.mtoggle,.dtoggle{display:none}

/* ---------- hero ---------- */
.hero{position:relative;overflow:hidden;background:var(--taupe-l)}
.hero-bg{position:absolute;inset:0;z-index:0}
.hero-bg img{width:100%;height:100%;object-fit:cover;object-position:62% 42%}
.hero-scrim{position:absolute;inset:0;z-index:1;pointer-events:none;
  background:linear-gradient(96deg,rgba(32,32,31,.82) 0%,rgba(32,32,31,.68) 30%,
    rgba(32,32,31,.30) 54%,rgba(32,32,31,.06) 76%,rgba(32,32,31,0) 100%)}
.hero-grid{position:relative;z-index:2;display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr);
  gap:60px;align-items:center;padding-top:118px;padding-bottom:118px}
.hero-txt{color:#fff;min-width:0}
.hero-txt .eyebrow{color:rgba(255,255,255,.78)}
h1{font-size:clamp(38px,5.2vw,66px);color:#fff;margin-bottom:24px;line-height:1.08}
h1 em{font-style:italic;color:var(--blush)}
.hero-lead{font-size:18px;color:rgba(255,255,255,.86);max-width:50ch;margin-bottom:34px;line-height:1.75}
.ticks{display:flex;flex-wrap:wrap;gap:12px 30px;margin-top:30px}
.tick{display:flex;align-items:center;gap:10px;font-size:13px;color:rgba(255,255,255,.82);
  letter-spacing:.03em}
.tick svg{width:15px;height:15px;flex-shrink:0}
.swap-tag{position:absolute;right:16px;bottom:16px;z-index:3;background:rgba(32,32,31,.6);
  color:#fff;font-size:10.5px;letter-spacing:.12em;text-transform:uppercase;padding:7px 15px;border-radius:var(--r)}

/* ---------- quick-start card (hero) ---------- */
.qs{background:var(--white);border:1px solid var(--line);box-shadow:var(--shadow-lg);
  padding:36px 34px;min-width:0}
.qs h2{font-size:26px;margin-bottom:8px}
.qs .qs-s{font-size:14.5px;color:var(--muted);margin-bottom:24px;line-height:1.6}
.qs form{display:grid;gap:16px;min-width:0}
.field{min-width:0}
.field>label{display:block;font-size:10.5px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;
  color:var(--muted);margin-bottom:8px}
input,select,textarea{min-width:0;width:100%;border:1px solid var(--line);border-radius:var(--r);
  padding:14px 15px;font-size:15px;font-family:var(--sans);color:var(--ink);background:var(--porcelain);
  appearance:none;transition:border-color .2s ease, box-shadow .2s ease}
input:focus,select:focus,textarea:focus{outline:none;border-color:var(--merlot);
  box-shadow:0 0 0 3px rgba(90,43,56,.12)}
select{background-image:linear-gradient(45deg,transparent 50%,var(--muted) 50%),
  linear-gradient(135deg,var(--muted) 50%,transparent 50%);
  background-position:calc(100% - 20px) 21px, calc(100% - 14px) 21px;
  background-size:6px 6px, 6px 6px;background-repeat:no-repeat;padding-right:42px}
textarea{resize:vertical;min-height:104px;line-height:1.6}
textarea::placeholder,input::placeholder{color:#9C948C;font-size:14px}
.frow{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px}
.frow>*{min-width:0}
.qs .btn,.enq .btn[type=submit]{width:100%}
.fnote{font-size:11.5px;color:var(--muted);line-height:1.6;text-align:center}
.opt-lbl{font-size:9.5px;letter-spacing:.12em;color:var(--merlot);background:var(--taupe-xl);
  padding:3px 9px;border-radius:var(--r);margin-left:8px}

/* ---------- 4-step form (pure CSS, no JS) ---------- */
.qs-head{margin-bottom:26px;padding-bottom:22px;border-bottom:1px solid var(--line)}
.qs-head h2{font-size:30px;margin-bottom:8px}
.stp{position:absolute;opacity:0;pointer-events:none;width:0;height:0}
.hp{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.stepper{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px;margin-bottom:28px}
.stepper label{display:flex;align-items:center;gap:9px;min-width:0;cursor:pointer;
  padding-top:13px;border-top:2px solid var(--line);transition:border-color .25s ease}
.stepper b{font-family:var(--serif);font-weight:400;font-size:13px;color:var(--muted);flex-shrink:0;
  transition:color .25s ease}
.stepper span{font-size:11px;letter-spacing:.11em;text-transform:uppercase;color:var(--muted);
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;transition:color .25s ease}
.pane{display:none;gap:18px}
#st1:checked ~ .panes .p1,#st2:checked ~ .panes .p2,
#st3:checked ~ .panes .p3,#st4:checked ~ .panes .p4{display:grid}
#st1:checked ~ .stepper label:nth-child(1),#st2:checked ~ .stepper label:nth-child(2),
#st3:checked ~ .stepper label:nth-child(3),#st4:checked ~ .stepper label:nth-child(4){border-top-color:var(--merlot)}
#st1:checked ~ .stepper label:nth-child(1) b,#st1:checked ~ .stepper label:nth-child(1) span,
#st2:checked ~ .stepper label:nth-child(2) b,#st2:checked ~ .stepper label:nth-child(2) span,
#st3:checked ~ .stepper label:nth-child(3) b,#st3:checked ~ .stepper label:nth-child(3) span,
#st4:checked ~ .stepper label:nth-child(4) b,#st4:checked ~ .stepper label:nth-child(4) span{color:var(--merlot)}
.nextb{cursor:pointer}
.btnrow{display:flex;gap:12px;flex-wrap:wrap}
.btnrow>*{flex:1 1 0;min-width:0}
.btnrow .btn-2{flex:0 0 auto;padding-left:26px;padding-right:26px}
.picks.tight label{padding:8px 15px;font-size:12.5px}
.consent{display:flex;gap:12px;align-items:flex-start;font-size:13.2px;color:var(--muted);
  line-height:1.6;cursor:pointer;min-width:0}
.consent input{width:17px;height:17px;flex-shrink:0;margin-top:3px;accent-color:var(--merlot);appearance:auto}
.mem-in{border-top:1px solid var(--line);padding-top:14px;margin-top:2px}
input[type=file]{padding:11px 14px;font-size:13.5px;background:var(--porcelain)}

/* ---------- assurance band ---------- */
.assure-band{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);gap:0;
  background:var(--white);border:1px solid var(--line)}
.assure-txt{padding:52px 50px;min-width:0}
.assure-txt .lead{margin-bottom:32px}
.assure-img{min-width:0}
.assure-img img{display:block;width:100%;height:100%;min-height:420px;object-fit:cover}

/* ---------- trust strip ---------- */
.strip{background:var(--ink);color:#E7E2DB}
.strip .wrap{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:26px;
  padding-top:30px;padding-bottom:30px}
.strip div{min-width:0;display:flex;align-items:center;gap:13px;font-size:13.2px;letter-spacing:.04em}
.strip svg{width:19px;height:19px;flex-shrink:0}

/* ---------- style / card tiles ---------- */
.tiles{display:grid;gap:26px}
.t6{grid-template-columns:repeat(6,minmax(0,1fr));gap:18px}
.t4{grid-template-columns:repeat(4,minmax(0,1fr))}
.t3{grid-template-columns:repeat(3,minmax(0,1fr))}
.t2{grid-template-columns:repeat(2,minmax(0,1fr))}
.tile{min-width:0;display:block;background:transparent}
.tile img{margin-bottom:16px;transition:opacity .3s ease}
.tile:hover img{opacity:.86}
.tile b{display:block;font-family:var(--serif);font-weight:400;font-size:20px;margin-bottom:6px}
.tile span{display:block;font-size:13.8px;color:var(--muted);line-height:1.6}
.tile .lnk{margin-top:13px}
.t6 .tile b{font-size:16.5px}
.t6 .tile span{font-size:12.6px}

/* ---------- bordered cards ---------- */
.card{min-width:0;display:flex;flex-direction:column;background:var(--white);
  border:1px solid var(--line);transition:border-color .25s ease, box-shadow .25s ease}
.card:hover{border-color:var(--taupe);box-shadow:var(--shadow)}
.card .cb{padding:28px 30px 30px;display:flex;flex-direction:column;flex:1}
.card h3{font-size:22px;margin-bottom:10px}
.card p{font-size:14.8px;color:var(--muted);line-height:1.7}
.card .lnk{margin-top:auto;padding-top:20px}
.kwl{margin-top:14px;font-size:12.6px;color:var(--muted);line-height:1.7}
.kwl b{color:var(--ink);font-weight:500}

/* ---------- how it works ---------- */
.steps{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0;
  border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.step{min-width:0;padding:46px 40px;border-right:1px solid var(--line)}
.step:last-child{border-right:0}
.step .n{font-family:var(--serif);font-size:15px;letter-spacing:.2em;color:var(--merlot);
  display:block;margin-bottom:20px}
.step h3{font-size:24px;margin-bottom:12px}
.step p{font-size:14.8px;color:var(--muted);line-height:1.7}

/* ---------- enquiry section ---------- */
.enq{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(0,.75fr);gap:0;
  background:var(--white);border:1px solid var(--line)}
.enq-main{padding:52px 50px;min-width:0}
.enq-main h2{margin-bottom:10px}
.enq-main>.lead{margin-bottom:32px;font-size:16px}
.enq form{display:grid;gap:18px;min-width:0}
.picks{display:flex;flex-wrap:wrap;gap:9px}
.picks label{display:inline-flex;align-items:center;font-size:13px;padding:9px 17px;
  border:1px solid var(--line);border-radius:var(--r);background:var(--porcelain);cursor:pointer;
  transition:background .18s ease, border-color .18s ease}
.picks input{position:absolute;opacity:0;width:0;height:0}
.picks label:hover{border-color:var(--taupe)}
.picks label:has(input:checked){background:var(--merlot);border-color:var(--merlot);color:#fff}
.enq-side{background:var(--taupe-xl);padding:52px 40px;min-width:0;border-left:1px solid var(--line)}
.enq-side h3{font-size:24px;margin-bottom:10px}
.enq-side>p{font-size:14.5px;color:var(--muted);line-height:1.7;margin-bottom:28px}
.assure{display:grid;gap:22px;margin-bottom:30px}
.assure div{display:flex;gap:14px;min-width:0}
.assure svg{width:20px;height:20px;flex-shrink:0;margin-top:3px}
.assure b{display:block;font-family:var(--serif);font-weight:400;font-size:17.5px;margin-bottom:3px}
.assure span{font-size:13.5px;color:var(--muted);line-height:1.65}
.privacy{border-top:1px solid var(--line);padding-top:22px;font-size:13px;color:var(--muted);line-height:1.7}
.privacy b{display:block;font-family:var(--serif);font-size:16px;color:var(--ink);margin-bottom:6px;font-weight:400}
.mem{display:flex;align-items:center;gap:18px;background:var(--taupe-xl);border:1px solid var(--line);
  border-top:0;padding:22px 30px;font-size:13.5px;color:var(--muted);line-height:1.65;min-width:0}
.mem svg{width:26px;height:26px;flex-shrink:0}
.mem b{color:var(--ink);font-weight:500}

/* ---------- real weddings ---------- */
.rw .tile img{aspect-ratio:4/5}
.rw-meta{font-size:10.5px;letter-spacing:.2em;text-transform:uppercase;color:var(--muted);
  display:block;margin-bottom:7px}

/* ---------- pricing feature ---------- */
.price-f{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);align-items:stretch;
  background:var(--merlot);color:#fff}
.price-img{min-width:0}
.price-img img{display:block;width:100%;height:100%;min-height:400px;object-fit:cover}
.price-txt{padding:60px 56px;min-width:0;display:flex;flex-direction:column;justify-content:center}
.price-txt .eyebrow{color:rgba(255,255,255,.62)}
.price-txt h2{color:#fff;margin-bottom:18px}
.price-txt>p{color:rgba(255,255,255,.82);font-size:16.5px;line-height:1.75;margin-bottom:28px}
.bands{display:grid;gap:0;margin-bottom:32px;border-top:1px solid rgba(255,255,255,.22)}
.bands div{display:flex;justify-content:space-between;gap:20px;padding:15px 0;
  border-bottom:1px solid rgba(255,255,255,.22);font-size:14.8px;min-width:0}
.bands span:first-child{color:rgba(255,255,255,.85)}
.bands span:last-child{font-family:var(--serif);font-size:17px;white-space:nowrap}
.price-note{font-size:12.5px;color:rgba(255,255,255,.6);margin-top:-16px;margin-bottom:26px}

/* ---------- locations ---------- */
.loc-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:36px}
.loc-col{min-width:0}
.loc-col h3{font-size:21px;margin-bottom:4px}
.loc-col .st{font-size:10.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--muted);
  display:block;margin-bottom:16px}
.loc-col li{border-bottom:1px solid var(--line)}
.loc-col a{display:block;font-size:14.6px;padding:9px 0;color:var(--ink);overflow-wrap:anywhere;
  transition:color .18s ease,padding .18s ease}
.loc-col a:hover{color:var(--merlot);padding-left:6px}
.pop{display:flex;flex-wrap:wrap;gap:10px;margin-top:18px}
.pop a{border:1px solid var(--line);padding:9px 19px;font-size:13.2px;background:var(--white);
  transition:.18s ease;border-radius:var(--r)}
.pop a:hover{border-color:var(--merlot);color:var(--merlot)}

/* ---------- faq ---------- */
.faq{max-width:900px;margin:0 auto;border-top:1px solid var(--line)}
.faq details{border-bottom:1px solid var(--line)}
.faq summary{cursor:pointer;list-style:none;padding:26px 58px 26px 0;position:relative;
  font-family:var(--serif);font-size:21px;color:var(--ink);transition:color .2s ease}
.faq summary:hover{color:var(--merlot)}
.faq summary::-webkit-details-marker{display:none}
.faq summary::after,.faq summary::before{content:"";position:absolute;right:12px;top:37px;
  background:var(--merlot);transition:transform .25s ease, opacity .25s ease}
.faq summary::after{width:15px;height:1px}
.faq summary::before{width:1px;height:15px;right:19px;top:30px}
.faq details[open] summary::before{opacity:0;transform:rotate(90deg)}
.faq .ans{padding:0 60px 28px 0;font-size:15.6px;color:var(--muted);line-height:1.8}

/* ---------- final CTA ---------- */
.band{position:relative;overflow:hidden;background:var(--merlot);color:#fff}
.band-img{position:absolute;inset:0;z-index:1}
.band-img img{width:100%;height:100%;object-fit:cover;opacity:.24}
.band-in{position:relative;z-index:2;padding:96px 44px;text-align:center}
.band h2{color:#fff;font-size:clamp(30px,4.2vw,52px);margin-bottom:18px}
.band h2 em{font-style:italic;color:var(--blush)}
.band p{color:rgba(255,255,255,.84);font-size:17.5px;max-width:52ch;margin:0 auto 36px}
.cta-row{display:flex;flex-wrap:wrap;gap:16px;justify-content:center}

/* ---------- footer ---------- */
footer{background:var(--ink);color:#A9A29A;padding-top:84px}
.f-top{display:grid;grid-template-columns:minmax(0,1.5fr) repeat(4,minmax(0,1fr));gap:40px;
  padding-bottom:56px;border-bottom:1px solid rgba(255,255,255,.13)}
.f-brand{min-width:0}
.f-brand .brand{color:#fff;display:inline-block;margin-bottom:18px}
.f-brand p{font-size:14.2px;line-height:1.75;max-width:32ch;margin-bottom:24px}
.f-col{min-width:0}
.f-col h3{font-family:var(--sans);font-weight:500;font-size:10.5px;letter-spacing:.2em;
  text-transform:uppercase;color:#fff;margin-bottom:18px}
.f-col li{margin-bottom:11px}
.f-col a{font-size:14px;overflow-wrap:anywhere;transition:color .18s ease}
.f-col a:hover{color:var(--blush)}
.f-bot{display:flex;flex-wrap:wrap;gap:16px 30px;align-items:center;justify-content:space-between;
  padding:28px 0 36px;font-size:12.8px;color:#7C766F}
.f-bot a:hover{color:var(--blush)}
.credit{display:inline-flex;align-items:center;gap:9px;white-space:nowrap}
.credit img{width:22px;height:22px;border-radius:5px;flex-shrink:0;display:block}

/* ---------- sticky mobile bar ---------- */
.sticky{display:none}

/* ---------- thank-you ---------- */
.ty{max-width:720px;margin:0 auto;text-align:center}
.ty-mark{width:78px;height:78px;border:1px solid var(--taupe);border-radius:50%;display:grid;
  place-items:center;margin:0 auto 30px}
.ty-mark svg{width:34px;height:34px}
.ty h1{color:var(--ink);font-size:clamp(34px,4.6vw,52px);margin-bottom:20px}
.ty>.lead{margin:0 auto 40px}
.ty-next{border-top:1px solid var(--line);text-align:left;margin-bottom:40px}
.ty-next li{display:flex;gap:22px;padding:26px 0;border-bottom:1px solid var(--line);min-width:0}
.ty-next b{font-family:var(--serif);font-size:15px;letter-spacing:.16em;color:var(--merlot);flex-shrink:0}
.ty-next span{display:block;min-width:0}
.ty-next strong{display:block;font-family:var(--serif);font-weight:400;font-size:20px;
  color:var(--ink);margin-bottom:5px}
.ty-next em{font-style:normal;font-size:14.8px;color:var(--muted);line-height:1.7}
.note{margin-top:36px;font-size:12.5px;color:var(--muted);border:1px dashed var(--taupe);
  padding:16px 22px;line-height:1.7}

/* ================= responsive ================= */
@media (max-width:1560px){ .nav a.top,.nav .drop-lbl{padding:10px 9px;font-size:11.4px;letter-spacing:.08em}
  .hdr{gap:18px} .brand{font-size:23px} }
@media (max-width:1400px){
  .burger{display:grid;place-items:center;width:46px;height:46px;border:1px solid var(--line);
    background:var(--white);cursor:pointer;margin-left:auto;flex-shrink:0;border-radius:var(--r)}
  .burger span{display:block;width:20px;height:1px;background:var(--ink);position:relative}
  .burger span::before,.burger span::after{content:"";position:absolute;left:0;width:20px;height:1px;background:var(--ink)}
  .burger span::before{top:-6px}.burger span::after{top:6px}
  .hdr-act{display:none}
  .nav{position:fixed;top:84px;left:0;right:0;bottom:0;margin:0;background:var(--porcelain);
    display:block;overflow-y:auto;padding:22px var(--gut) 48px;
    clip-path:inset(0 0 0 100%);pointer-events:none;opacity:0;
    transition:clip-path .34s ease, opacity .28s ease;z-index:70}
  .mtoggle:checked ~ .nav{clip-path:inset(0 0 0 0);pointer-events:auto;opacity:1}
  .nav>li{border-bottom:1px solid var(--line)}
  .nav a.top,.nav .drop-lbl{padding:18px 2px;font-size:13px;letter-spacing:.14em;justify-content:space-between}
  .nav .caret{width:11px;height:11px;transition:transform .22s ease}
  .menu{position:static;opacity:1;visibility:visible;transform:none;box-shadow:none;border:0;
    padding:0 0 16px;min-width:0;max-height:0;overflow:hidden;transition:max-height .34s ease;background:transparent}
  .dtoggle:checked + .drop-lbl + .menu{max-height:900px}
  .dtoggle:checked + .drop-lbl .caret{transform:rotate(180deg)}
  .menu a{padding:9px 0;font-size:16px;color:var(--muted)}
  .menu .mh{padding-left:0}
  .nav-cta{display:flex!important;flex-direction:column;gap:12px;padding-top:26px;border:0!important}
  .nav-cta .btn{width:100%}
}
@media (max-width:1100px){
  .hero-grid{grid-template-columns:minmax(0,1fr);gap:46px;padding-top:76px;padding-bottom:76px}
  .hero-scrim{background:linear-gradient(180deg,rgba(32,32,31,.60) 0%,rgba(32,32,31,.70) 40%,rgba(32,32,31,.78) 100%)}
  .hero-bg img{object-position:50% 38%}
  .qs{max-width:580px}
  .swap-tag{display:none}
  .t6{grid-template-columns:repeat(3,minmax(0,1fr))}
  .t4,.t3,.t2{grid-template-columns:repeat(2,minmax(0,1fr))}
  .steps{grid-template-columns:minmax(0,1fr)}
  .step{border-right:0;border-bottom:1px solid var(--line);padding:36px 0}
  .step:last-child{border-bottom:0}
  .enq,.price-f,.assure-band{grid-template-columns:minmax(0,1fr)}
  .enq-main{padding:40px 32px}
  .enq-side{border-left:0;border-top:1px solid var(--line);padding:40px 32px}
  .assure-txt{padding:40px 32px}
  .assure-img{order:-1}
  .assure-img img{min-height:260px}
  .qs{max-width:none}
  .price-img img{min-height:280px}
  .price-txt{padding:44px 34px}
  .loc-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:30px}
  .strip .wrap{grid-template-columns:repeat(2,minmax(0,1fr))}
  .f-top{grid-template-columns:repeat(3,minmax(0,1fr))}
  .f-brand{grid-column:1/-1}
}
@media (max-width:768px){
  :root{--gut:26px}
  .sec{padding-top:70px;padding-bottom:70px}
  .sec-t{padding-top:54px;padding-bottom:54px}
  .nav{top:74px}
  .hdr{min-height:74px}
  .brand{font-size:22px}
  .band-in{padding:64px 24px}
  .qs{padding:28px 24px}
  .stepper{grid-template-columns:repeat(4,minmax(0,1fr));gap:4px}
  .stepper span{display:none}
  .stepper label{justify-content:center;padding-top:11px}
  .stepper b{font-size:12px}
  .sticky{display:flex;position:fixed;left:0;right:0;bottom:0;z-index:80;gap:11px;
    background:rgba(248,244,237,.97);backdrop-filter:blur(12px);border-top:1px solid var(--line);
    padding:11px 16px calc(11px + env(safe-area-inset-bottom))}
  .sticky .btn{flex:1 1 0;min-width:0;padding:15px 10px;font-size:11px;letter-spacing:.1em}
  footer{padding-bottom:82px}
}
@media (max-width:620px){
  .t6,.t4,.t3,.t2,.loc-grid,.f-top{grid-template-columns:minmax(0,1fr)}
  .strip .wrap{grid-template-columns:minmax(0,1fr);gap:16px}
  .frow{grid-template-columns:minmax(0,1fr)}
  .f-top{gap:30px}
  .rw .tile img{aspect-ratio:4/3}
}
@media (max-width:430px){
  :root{--gut:20px}
  .enq-main,.enq-side,.price-txt,.assure-txt{padding:32px 22px}
  .btnrow{flex-direction:column}
  .btnrow>*{width:100%}
  .card .cb{padding:24px 22px 26px}
  .cta-row .btn{width:100%}
  .btn{white-space:normal;text-align:center;padding-left:20px;padding-right:20px;max-width:100%}
  .faq summary{font-size:19px;padding-right:44px}
}

*{box-sizing:border-box}
svg{width:18px;height:18px;flex-shrink:0}
:root{
 /* Palette from the Aisle & Stem Integrated Visual Developer Guide */
 --porcelain:#F8F4ED; --merlot:#5A2B38; --taupe:#C8B9AA; --ink:#20201F;
 --merlot-d:#46212B; --merlot-l:#7A4353; --blush:#EFE3E4;
 --paper:#FFFFFF; --sand:#F2EBE1; --taupe-s:#EDE4D9; --soft:#6B6560; --line:#E3D9CC;
 --gut:clamp(18px,5vw,54px); --r:2px;
 --dsp:'EB Garamond',Georgia,'Times New Roman',serif;
 --bdy:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;
}
html{scroll-behavior:smooth}
body{margin:0;background:var(--porcelain);color:var(--ink);font:400 16px/1.72 var(--bdy);-webkit-font-smoothing:antialiased}
img{max-width:100%;display:block}
a{color:var(--merlot)}
.wrap{max-width:1280px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
h1,h2,h3{font-family:var(--dsp);font-weight:500;line-height:1.12;margin:0;letter-spacing:-.004em}
h1{font-size:clamp(34px,4.2vw,52px)}
h2{font-size:clamp(28px,3.6vw,44px)}
h3{font-size:clamp(19px,1.9vw,23px);line-height:1.3}
p{margin:0 0 16px}
.eyebrow{font:500 10.8px/1 var(--bdy);letter-spacing:.24em;text-transform:uppercase;color:var(--merlot);margin:0 0 16px;display:block}
.lede{font-size:clamp(16.5px,1.5vw,18.5px);color:#443F3B;line-height:1.7}
.sec{padding:clamp(56px,6.5vw,104px) 0}
.sec.alt{background-color:var(--paper)}
.sec.sand{background-color:var(--sand)}
.rv{animation:rvIn .85s both}
.rv2{animation-delay:.09s}.rv3{animation-delay:.18s}.rv4{animation-delay:.27s}
@keyframes rvIn{from{opacity:0;transform:translateY(22px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.rv{animation:none}}
.skip{position:absolute;left:-9999px;top:0;background:var(--merlot);color:#fff;padding:12px 18px;z-index:200}
.skip:focus{left:8px;top:8px}
a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible,label:focus-visible{outline:2.5px solid var(--merlot);outline-offset:3px}
.ph-img{width:100%;object-fit:cover;background:var(--taupe-s)}
/* interior pages */
.crumb{font:400 12.6px/1.6 var(--bdy);color:var(--soft);padding-top:20px}
.crumb a{color:var(--soft);text-decoration:none}
.crumb a:hover{color:var(--merlot)}
.crumb span{color:var(--taupe);margin:0 7px}
.crumb b{color:var(--ink);font-weight:500}
.sub{background-color:var(--porcelain);border-bottom:1px solid var(--line)}
.sub-in{display:grid;grid-template-columns:1.08fr .92fr;gap:clamp(28px,4vw,60px);align-items:center;
 padding-top:clamp(30px,3.6vw,52px);padding-bottom:clamp(40px,4.6vw,68px)}
.sub-in>*{min-width:0}
.sub h1{margin-bottom:20px}
.sub .ph-img{aspect-ratio:4/3}
.sub-solo{max-width:840px;padding-top:clamp(28px,3.4vw,46px);padding-bottom:clamp(40px,4.6vw,66px)}
.prose{max-width:820px}
.prose h2{margin-top:clamp(36px,4vw,58px);margin-bottom:14px}
.prose h2:first-child{margin-top:0}
.prose h3{margin-top:30px;margin-bottom:10px}
.prose p{font-size:16.4px;line-height:1.78;color:#443F3B}
.prose ul.b{list-style:none;margin:14px 0 20px;padding:0}
.prose ul.b li{position:relative;padding-left:24px;margin-bottom:10px;font-size:16px;line-height:1.72;color:#443F3B}
.prose ul.b li::before{content:"";position:absolute;left:2px;top:11px;width:7px;height:7px;border:1px solid var(--merlot);transform:rotate(45deg)}
.prose .tw{margin:20px 0 8px}
.note{background-color:var(--sand);border-left:2px solid var(--merlot);padding:18px 22px;margin:22px 0;font-size:15.4px;line-height:1.7;color:#443F3B}
.note b{color:var(--ink)}
.faq{max-width:820px;margin-top:clamp(30px,3.4vw,44px)}
.glist{display:grid;gap:16px}
.gl{display:grid;grid-template-columns:1fr 220px;gap:24px;align-items:center;background-color:var(--paper);border:1px solid var(--line);padding:clamp(22px,2.6vw,34px);text-decoration:none;transition:border-color .2s,transform .2s}
.gl:hover{border-color:var(--merlot);transform:translateY(-2px)}
.gl h3{font-family:var(--dsp);font-size:clamp(21px,2.1vw,26px);font-weight:500;color:var(--ink);margin:10px 0 8px;line-height:1.25}
.gl p{font-size:15px;color:var(--soft);line-height:1.65;margin:0 0 14px;max-width:62ch}
.gl .tag{display:inline-block;font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--merlot);font-weight:600}
.gl-r{font-size:13px;color:var(--soft);text-align:right;border-left:1px solid var(--line);padding-left:24px}
.gl-r b{display:block;color:var(--ink);font-weight:500;margin-top:4px}
@media (max-width:820px){.gl{grid-template-columns:1fr;gap:14px}.gl-r{text-align:left;border-left:0;border-top:1px solid var(--line);padding:14px 0 0}}
.prose p.upd{font-size:13px;color:var(--soft);border-left:2px solid var(--taupe);padding-left:14px;margin-top:26px;font-style:italic}
details{border-bottom:1px solid var(--line)}
summary{padding:18px 2px;cursor:pointer;font:500 16.4px/1.5 var(--bdy);color:var(--ink);list-style:none;display:flex;justify-content:space-between;gap:18px;align-items:flex-start}
summary::-webkit-details-marker{display:none}
summary::after{content:"";width:9px;height:9px;border-right:1.6px solid var(--merlot);border-bottom:1.6px solid var(--merlot);transform:rotate(45deg);flex-shrink:0;margin-top:7px;transition:.2s}
details[open] summary::after{transform:rotate(-135deg)}
details .a{padding:0 2px 20px;font-size:15.6px;color:#443F3B;line-height:1.76;max-width:74ch}
details .a p:last-child{margin-bottom:0}
.side{background-color:var(--paper);border:1px solid var(--line);padding:24px 26px;position:sticky;top:96px}
.side h3{font-size:20px;margin-bottom:12px}
.side ul{list-style:none;margin:0;padding:0}
.side li{border-bottom:1px solid #F1EAE0}
.side li:last-child{border-bottom:0}
.side a{display:block;padding:11px 0;font-size:14.8px;color:#443F3B;text-decoration:none}
.side a:hover{color:var(--merlot)}
.split{display:grid;grid-template-columns:1fr 320px;gap:clamp(30px,4vw,56px);align-items:start}
.split>*{min-width:0}
@media (max-width:1080px){.sub-in{grid-template-columns:1fr}.sub .shot{order:-1}.split{grid-template-columns:1fr}
.side{position:static;top:auto}}
/* botanical watermark, opacity baked into the PNG so no pseudo-element or z-index is needed */
.wm{background-image:var(--pat);background-repeat:repeat;background-size:440px 440px;background-position:center top}
@media (max-width:700px){.wm{background-size:300px 300px}}

/* header */
header{position:sticky;top:0;z-index:120;background:rgba(248,244,237,.95);backdrop-filter:saturate(1.3) blur(10px);border-bottom:1px solid var(--line)}
.hdr-in{max-width:1280px;margin:0 auto;padding:0 var(--gut);display:flex;align-items:center;gap:18px;min-height:94px}
.brand{display:flex;align-items:center;flex-shrink:0;margin-right:auto}
.brand img{height:50px;width:auto}
.nav{display:flex;align-items:center;gap:0;list-style:none;margin:0;padding:0}
.nav>li{position:relative}
.nav>li>a,.drop-lbl{display:flex;align-items:center;gap:5px;padding:10px 13px;font:400 13.8px/1 var(--bdy);letter-spacing:.02em;color:var(--ink);text-decoration:none;cursor:pointer;white-space:nowrap}
.nav>li>a:hover,.drop-lbl:hover{color:var(--merlot)}
.caret{width:10px;height:10px;transition:transform .2s;opacity:.55}
.menu{position:absolute;top:calc(100% + 6px);left:0;min-width:272px;background:var(--paper);border:1px solid var(--line);padding:8px;box-shadow:0 22px 50px rgba(32,32,31,.13);list-style:none;margin:0;opacity:0;visibility:hidden;transform:translateY(-6px);transition:.16s}
.nav>li:hover>.menu,.nav>li:focus-within>.menu{opacity:1;visibility:visible;transform:none}
.menu a{display:block;padding:9px 13px;font:400 13.9px/1.45 var(--bdy);color:#443F3B;text-decoration:none}
.menu a:hover{background:var(--sand);color:var(--merlot)}
.menu .grp{padding:11px 13px 4px;font:500 10px/1 var(--bdy);letter-spacing:.18em;text-transform:uppercase;color:var(--soft)}
.hdr-cta{flex-shrink:0;margin-left:10px}
.burger,.dtog{position:absolute;opacity:0;pointer-events:none;width:0;height:0}
.burg-lbl{display:none;cursor:pointer;padding:10px;margin-left:auto;border:1px solid var(--line);background:var(--paper)}
.burg-lbl svg{width:22px;height:22px}
/* buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;padding:15px 30px;font:500 12.4px/1 var(--bdy);letter-spacing:.13em;text-transform:uppercase;text-decoration:none;border:1px solid transparent;cursor:pointer;transition:.18s;text-align:center}
.btn-p{background:var(--merlot);color:#fff}
.btn-p:hover{background:var(--merlot-d)}
.btn-s{background:transparent;color:var(--ink);border-color:var(--ink)}
.btn-s:hover{background:var(--ink);color:#fff}
.btn-w{background:transparent;color:#fff;border-color:rgba(255,255,255,.55)}
.btn-w:hover{background:#fff;color:var(--merlot)}
.btn-sm{padding:12px 22px;font-size:11.4px}
/* hero */
.hero{position:relative;background-color:var(--porcelain)}
.hero-in{display:grid;grid-template-columns:1.02fr .98fr;gap:0;align-items:stretch;min-height:min(76vh,660px)}
.hero-in>*{min-width:0}
.hero-txt{padding:clamp(44px,5.5vw,84px) clamp(24px,4vw,64px) clamp(44px,5.5vw,84px) var(--gut);display:flex;flex-direction:column;justify-content:center;max-width:760px;margin-left:auto;width:100%}
.hero h1{margin-bottom:22px}
.ans{border-left:2px solid var(--merlot);padding:4px 0 4px 20px;margin:0 0 30px;font-size:16.6px;line-height:1.72;color:#443F3B}
.hero-cta{display:flex;flex-wrap:wrap;gap:12px;margin-bottom:24px}
.hero-note{font-size:13.2px;color:var(--soft);display:flex;align-items:center;gap:9px;margin:0}
.hero-note svg{width:15px;height:15px;color:var(--merlot)}
.hero-img{position:relative}
.hero-img .ph-img{height:100%;min-height:340px}
/* strip */
.strip{background-color:var(--ink);color:#E8E3DC}
.strip-in{display:grid;grid-template-columns:repeat(4,1fr);gap:28px;padding-top:32px;padding-bottom:32px}
.strip-in>div{min-width:0}
.strip b{display:block;font-family:var(--dsp);font-size:23px;font-weight:500;color:#fff;line-height:1.25;margin-bottom:4px}
.strip span{font-size:12.9px;color:#B3ACA3;line-height:1.55;display:block}
/* layout */
.head{max-width:790px;margin-bottom:clamp(30px,3.6vw,52px)}
.head.mid{margin-left:auto;margin-right:auto;text-align:center}
.grid{display:grid;gap:clamp(16px,1.8vw,26px)}
.grid>*{min-width:0}
.g2{grid-template-columns:repeat(2,minmax(0,1fr))}
.g3{grid-template-columns:repeat(3,minmax(0,1fr))}
.g4{grid-template-columns:repeat(4,minmax(0,1fr))}
/* photo cards */
.pc{background:var(--paper);border:1px solid var(--line);display:flex;flex-direction:column;text-decoration:none;color:inherit;transition:.2s}
.pc:hover{border-color:var(--taupe);box-shadow:0 16px 40px rgba(32,32,31,.08);transform:translateY(-3px)}
.pc .ph-img{aspect-ratio:4/3}
.pc-b{padding:22px 24px 24px;display:flex;flex-direction:column;flex:1}
.pc-b h2,.pc-b h3{font-size:clamp(20px,2vw,25px);margin-bottom:9px}
.pc-b p{font-size:14.8px;color:#4E4842;margin-bottom:16px;line-height:1.66}
.go{margin-top:auto;font:500 11.4px/1 var(--bdy);letter-spacing:.14em;text-transform:uppercase;color:var(--merlot);text-decoration:none;display:inline-flex;align-items:center;gap:8px}
.go svg{width:13px;height:13px;transition:.2s}
.pc:hover .go svg,.go:hover svg{transform:translateX(4px)}
.pc-kicker{font:500 10.2px/1 var(--bdy);letter-spacing:.2em;text-transform:uppercase;color:var(--soft);margin-bottom:9px;display:block}
/* work grid */
.work .ph-img{aspect-ratio:3/3.6}
.work .cap{padding:14px 2px 0}
.work .cap b{display:block;font-family:var(--dsp);font-size:19px;font-weight:500;margin-bottom:2px}
.work .cap span{font-size:12.6px;color:var(--soft)}
/* table */
.tw{overflow-x:auto;border:1px solid var(--line);background:var(--paper)}
table{width:100%;border-collapse:collapse;font-size:14.8px;min-width:580px}
th{text-align:left;padding:15px 20px;background:var(--sand);font:500 10.6px/1.3 var(--bdy);letter-spacing:.15em;text-transform:uppercase;color:var(--soft);border-bottom:1px solid var(--line)}
td{padding:15px 20px;border-bottom:1px solid #F0E9DF;color:#4E4842;vertical-align:top}
tr:last-child td{border-bottom:0}
td b{color:var(--ink);font-weight:600}
/* steps */
.steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:clamp(18px,2.4vw,36px);counter-reset:s}
.step{min-width:0}
.step-n{counter-increment:s;font-family:var(--dsp);font-size:15px;color:var(--merlot);letter-spacing:.14em;margin-bottom:14px;display:block;padding-bottom:12px;border-bottom:1px solid var(--taupe)}
.step-n::before{content:"0" counter(s)}
.step h3{margin-bottom:7px;font-size:21px}
.step p{margin:0;font-size:14.8px;color:#4E4842;line-height:1.68}
/* cta strip */
.band{background-color:var(--merlot);color:#fff;position:relative;overflow:hidden}
.band-in{display:grid;grid-template-columns:1.25fr .75fr;gap:0;align-items:stretch}
.band-in>*{min-width:0}
.band-t{padding:clamp(46px,5.5vw,80px) clamp(28px,4vw,56px) clamp(46px,5.5vw,80px) var(--gut);display:flex;flex-direction:column;justify-content:center}
.band h2{color:#fff;font-size:clamp(28px,3.4vw,42px);margin-bottom:12px;max-width:16ch}
.band p{color:#E2CFD4;margin:0 0 26px;font-size:16px;max-width:46ch}
.band .ph-img{height:100%;min-height:240px}
/* enquiry */
.quote-in{display:grid;grid-template-columns:.9fr 1.1fr;gap:clamp(30px,4.5vw,62px);align-items:center}
.quote-in>*{min-width:0}
.qlist{list-style:none;margin:26px 0 0;padding:0}
.qlist li{display:flex;gap:12px;align-items:flex-start;margin-bottom:13px;font-size:15.2px;color:#4E4842}
.qlist svg{width:16px;height:16px;color:var(--merlot);margin-top:4px}
.fbox{background:var(--paper);border:1px solid var(--line);padding:clamp(24px,3vw,38px)}
.fbox-t{font-family:var(--dsp);font-size:clamp(22px,2.2vw,28px);font-weight:500;line-height:1.24;margin:0 0 6px}
.fbox .sm{font-size:13.4px;color:var(--soft);margin-bottom:22px}
.frow{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}
.frow>*{min-width:0}
.field{margin-bottom:15px;min-width:0}
.field label{display:block;font:500 11.4px/1 var(--bdy);letter-spacing:.1em;text-transform:uppercase;color:var(--soft);margin-bottom:8px}
.req{color:var(--merlot)}
input,select,textarea{width:100%;min-width:0;padding:13px 15px;border:1px solid var(--line);font:400 15px/1.45 var(--bdy);color:var(--ink);background:var(--paper);border-radius:0}
textarea{min-height:106px;resize:vertical}
select option{background:#fff;color:var(--ink)}
input:hover,select:hover,textarea:hover{border-color:var(--taupe)}
input:focus,select:focus,textarea:focus{border-color:var(--merlot)}
.fnote{font-size:12.4px;color:var(--soft);margin:15px 0 0;line-height:1.6}
/* footer */
footer{background-color:var(--ink);color:#B3ACA3;padding-top:clamp(48px,6vw,76px);padding-bottom:30px}
.f-top{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr 1fr;gap:34px;padding-bottom:42px;border-bottom:1px solid rgba(255,255,255,.1)}
.f-top>*{min-width:0}
.f-brand img{height:54px;width:auto;margin-bottom:22px}
.f-desc{font-size:14.2px;color:#C0B9AF;line-height:1.72;max-width:330px}
.f-tag{font-family:var(--dsp);font-size:20px;color:#fff;margin:16px 0 0;line-height:1.4}
footer h4{font:500 10.4px/1 var(--bdy);letter-spacing:.18em;text-transform:uppercase;color:#fff;margin:0 0 16px}
footer ul{list-style:none;margin:0;padding:0}
footer li{margin-bottom:10px}
footer a{color:#B3ACA3;text-decoration:none;font-size:14px;line-height:1.5}
footer a:hover{color:#fff}
.f-bot{display:flex;flex-wrap:wrap;gap:14px;justify-content:space-between;align-items:center;padding-top:26px;font-size:12.8px;color:#8A837B}
.built{display:inline-flex;align-items:center;gap:9px}
.built-ico{width:22px;height:22px}
.built b{color:var(--taupe);font-weight:600}
.pend{background:rgba(200,185,170,.13);border:1px solid rgba(200,185,170,.3);color:#D6CEC3;padding:11px 14px;font-size:12.2px;line-height:1.6;margin-top:18px}
.top{position:fixed;right:18px;bottom:18px;z-index:90;width:44px;height:44px;background:var(--merlot);color:#fff;display:flex;align-items:center;justify-content:center;text-decoration:none}
.top svg{width:18px;height:18px}
/* responsive */
@media (max-width:1240px){.nav>li>a,.drop-lbl{padding:10px 10px;font-size:13.2px}}
@media (max-width:1080px){
 .hero-in{grid-template-columns:1fr;min-height:0}
 .hero-txt{padding:clamp(38px,6vw,60px) var(--gut);max-width:none;order:2}
 .hero-img{order:1}.hero-img .ph-img{aspect-ratio:16/9;min-height:0}
 .band-in{grid-template-columns:1fr}.band-t{padding:clamp(42px,6vw,62px) var(--gut)}
 .band .ph-img{aspect-ratio:16/7;min-height:0}
 .quote-in{grid-template-columns:1fr}
 .strip-in{grid-template-columns:repeat(2,1fr);gap:24px}
 .g4,.g3{grid-template-columns:repeat(2,minmax(0,1fr))}
 .steps{grid-template-columns:repeat(2,minmax(0,1fr));gap:28px}
 .burg-lbl{display:block}.hdr-cta{display:none}
 .f-top{grid-template-columns:1.4fr 1fr 1fr;gap:28px}
 .nav{position:absolute;top:100%;left:0;right:0;flex-direction:column;align-items:stretch;background:var(--paper);border-bottom:1px solid var(--line);box-shadow:0 20px 40px rgba(32,32,31,.12);padding:8px var(--gut) 24px;max-height:0;overflow:hidden;visibility:hidden;transition:max-height .28s ease,visibility 0s .28s}
 .burger:checked ~ .nav{max-height:78vh;overflow-y:auto;visibility:visible;transition:max-height .3s ease,visibility 0s}
 .nav>li>a,.drop-lbl{padding:14px 2px;font-size:15.6px;border-bottom:1px solid #F1EAE0;justify-content:space-between}
 .menu{position:static;opacity:1;visibility:visible;transform:none;border:0;box-shadow:none;padding:0 0 6px 12px;min-width:0;max-height:0;overflow:hidden;background:transparent;transition:max-height .26s ease}
 .dtog:checked ~ .menu{max-height:760px}
 .dtog:checked ~ .drop-lbl .caret{transform:rotate(180deg)}
 .nav>li:hover>.menu,.nav>li:focus-within>.menu{opacity:1;visibility:visible}
 .mob-cta{display:block;margin-top:20px}
 .mob-cta .btn{width:100%;color:#fff;background:var(--merlot);border:1px solid var(--merlot);border-bottom:1px solid var(--merlot);justify-content:center;padding:16px 26px;font-size:12px}
 .mob-cta .btn:hover{background:var(--merlot-d);color:#fff}
}
@media (min-width:1081px){.mob-cta{display:none}}
@media (max-width:660px){
 .strip-in{grid-template-columns:1fr;gap:18px}
 .g2,.g3,.g4,.steps{grid-template-columns:1fr}
 .frow{grid-template-columns:1fr}
 .f-top{grid-template-columns:1fr;gap:28px}
 .work .ph-img{aspect-ratio:4/3}
}


:root{--pat:url('data:image/png;base64,')}

*{box-sizing:border-box}
svg{width:18px;height:18px;flex-shrink:0}
:root{
 /* Palette from the Aisle & Stem Integrated Visual Developer Guide */
 --porcelain:#F8F4ED; --merlot:#5A2B38; --taupe:#C8B9AA; --ink:#20201F;
 --merlot-d:#46212B; --merlot-l:#7A4353; --blush:#EFE3E4;
 --paper:#FFFFFF; --sand:#F2EBE1; --taupe-s:#EDE4D9; --soft:#6B6560; --line:#E3D9CC;
 --gut:clamp(18px,5vw,54px); --r:2px;
 --dsp:'EB Garamond',Georgia,'Times New Roman',serif;
 --bdy:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;
}
html{scroll-behavior:smooth}
body{margin:0;background:var(--porcelain);color:var(--ink);font:400 16px/1.72 var(--bdy);-webkit-font-smoothing:antialiased}
img{max-width:100%;display:block}
a{color:var(--merlot)}
.wrap{max-width:1280px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
h1,h2,h3{font-family:var(--dsp);font-weight:500;line-height:1.12;margin:0;letter-spacing:-.004em}
h1{font-size:clamp(34px,4.2vw,52px)}
h2{font-size:clamp(28px,3.6vw,44px)}
h3{font-size:clamp(19px,1.9vw,23px);line-height:1.3}
p{margin:0 0 16px}
.eyebrow{font:500 10.8px/1 var(--bdy);letter-spacing:.24em;text-transform:uppercase;color:var(--merlot);margin:0 0 16px;display:block}
.lede{font-size:clamp(16.5px,1.5vw,18.5px);color:#443F3B;line-height:1.7}
.sec{padding:clamp(56px,6.5vw,104px) 0}
.sec.alt{background-color:var(--paper)}
.sec.sand{background-color:var(--sand)}
.rv{animation:rvIn .85s both}
.rv2{animation-delay:.09s}.rv3{animation-delay:.18s}.rv4{animation-delay:.27s}
@keyframes rvIn{from{opacity:0;transform:translateY(22px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.rv{animation:none}}
.skip{position:absolute;left:-9999px;top:0;background:var(--merlot);color:#fff;padding:12px 18px;z-index:200}
.skip:focus{left:8px;top:8px}
a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible,label:focus-visible{outline:2.5px solid var(--merlot);outline-offset:3px}
.ph-img{width:100%;object-fit:cover;background:var(--taupe-s)}
/* interior pages */
.crumb{font:400 12.6px/1.6 var(--bdy);color:var(--soft);padding-top:20px}
.crumb a{color:var(--soft);text-decoration:none}
.crumb a:hover{color:var(--merlot)}
.crumb span{color:var(--taupe);margin:0 7px}
.crumb b{color:var(--ink);font-weight:500}
.sub{background-color:var(--porcelain);border-bottom:1px solid var(--line)}
.sub-in{display:grid;grid-template-columns:1.08fr .92fr;gap:clamp(28px,4vw,60px);align-items:center;
 padding-top:clamp(30px,3.6vw,52px);padding-bottom:clamp(40px,4.6vw,68px)}
.sub-in>*{min-width:0}
.sub h1{margin-bottom:20px}
.sub .ph-img{aspect-ratio:4/3}
.sub-solo{max-width:840px;padding-top:clamp(28px,3.4vw,46px);padding-bottom:clamp(40px,4.6vw,66px)}
.prose{max-width:820px}
.prose h2{margin-top:clamp(36px,4vw,58px);margin-bottom:14px}
.prose h2:first-child{margin-top:0}
.prose h3{margin-top:30px;margin-bottom:10px}
.prose p{font-size:16.4px;line-height:1.78;color:#443F3B}
.prose ul.b{list-style:none;margin:14px 0 20px;padding:0}
.prose ul.b li{position:relative;padding-left:24px;margin-bottom:10px;font-size:16px;line-height:1.72;color:#443F3B}
.prose ul.b li::before{content:"";position:absolute;left:2px;top:11px;width:7px;height:7px;border:1px solid var(--merlot);transform:rotate(45deg)}
.prose .tw{margin:20px 0 8px}
.note{background-color:var(--sand);border-left:2px solid var(--merlot);padding:18px 22px;margin:22px 0;font-size:15.4px;line-height:1.7;color:#443F3B}
.note b{color:var(--ink)}
.faq{max-width:820px;margin-top:clamp(30px,3.4vw,44px)}
.glist{display:grid;gap:16px}
.gl{display:grid;grid-template-columns:1fr 220px;gap:24px;align-items:center;background-color:var(--paper);border:1px solid var(--line);padding:clamp(22px,2.6vw,34px);text-decoration:none;transition:border-color .2s,transform .2s}
.gl:hover{border-color:var(--merlot);transform:translateY(-2px)}
.gl h3{font-family:var(--dsp);font-size:clamp(21px,2.1vw,26px);font-weight:500;color:var(--ink);margin:10px 0 8px;line-height:1.25}
.gl p{font-size:15px;color:var(--soft);line-height:1.65;margin:0 0 14px;max-width:62ch}
.gl .tag{display:inline-block;font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--merlot);font-weight:600}
.gl-r{font-size:13px;color:var(--soft);text-align:right;border-left:1px solid var(--line);padding-left:24px}
.gl-r b{display:block;color:var(--ink);font-weight:500;margin-top:4px}
@media (max-width:820px){.gl{grid-template-columns:1fr;gap:14px}.gl-r{text-align:left;border-left:0;border-top:1px solid var(--line);padding:14px 0 0}}
.prose p.upd{font-size:13px;color:var(--soft);border-left:2px solid var(--taupe);padding-left:14px;margin-top:26px;font-style:italic}
details{border-bottom:1px solid var(--line)}
summary{padding:18px 2px;cursor:pointer;font:500 16.4px/1.5 var(--bdy);color:var(--ink);list-style:none;display:flex;justify-content:space-between;gap:18px;align-items:flex-start}
summary::-webkit-details-marker{display:none}
summary::after{content:"";width:9px;height:9px;border-right:1.6px solid var(--merlot);border-bottom:1.6px solid var(--merlot);transform:rotate(45deg);flex-shrink:0;margin-top:7px;transition:.2s}
details[open] summary::after{transform:rotate(-135deg)}
details .a{padding:0 2px 20px;font-size:15.6px;color:#443F3B;line-height:1.76;max-width:74ch}
details .a p:last-child{margin-bottom:0}
.side{background-color:var(--paper);border:1px solid var(--line);padding:24px 26px;position:sticky;top:96px}
.side h3{font-size:20px;margin-bottom:12px}
.side ul{list-style:none;margin:0;padding:0}
.side li{border-bottom:1px solid #F1EAE0}
.side li:last-child{border-bottom:0}
.side a{display:block;padding:11px 0;font-size:14.8px;color:#443F3B;text-decoration:none}
.side a:hover{color:var(--merlot)}
.split{display:grid;grid-template-columns:1fr 320px;gap:clamp(30px,4vw,56px);align-items:start}
.split>*{min-width:0}
@media (max-width:1080px){.sub-in{grid-template-columns:1fr}.sub .shot{order:-1}.split{grid-template-columns:1fr}
.side{position:static;top:auto}}
/* botanical watermark, opacity baked into the PNG so no pseudo-element or z-index is needed */
.wm{background-image:var(--pat);background-repeat:repeat;background-size:440px 440px;background-position:center top}
@media (max-width:700px){.wm{background-size:300px 300px}}

/* header */
header{position:sticky;top:0;z-index:120;background:rgba(248,244,237,.95);backdrop-filter:saturate(1.3) blur(10px);border-bottom:1px solid var(--line)}
.hdr-in{max-width:1280px;margin:0 auto;padding:0 var(--gut);display:flex;align-items:center;gap:18px;min-height:94px}
.brand{display:flex;align-items:center;flex-shrink:0;margin-right:auto}
.brand img{height:50px;width:auto}
.nav{display:flex;align-items:center;gap:0;list-style:none;margin:0;padding:0}
.nav>li{position:relative}
.nav>li>a,.drop-lbl{display:flex;align-items:center;gap:5px;padding:10px 13px;font:400 13.8px/1 var(--bdy);letter-spacing:.02em;color:var(--ink);text-decoration:none;cursor:pointer;white-space:nowrap}
.nav>li>a:hover,.drop-lbl:hover{color:var(--merlot)}
.caret{width:10px;height:10px;transition:transform .2s;opacity:.55}
.menu{position:absolute;top:calc(100% + 6px);left:0;min-width:272px;background:var(--paper);border:1px solid var(--line);padding:8px;box-shadow:0 22px 50px rgba(32,32,31,.13);list-style:none;margin:0;opacity:0;visibility:hidden;transform:translateY(-6px);transition:.16s}
.nav>li:hover>.menu,.nav>li:focus-within>.menu{opacity:1;visibility:visible;transform:none}
.menu a{display:block;padding:9px 13px;font:400 13.9px/1.45 var(--bdy);color:#443F3B;text-decoration:none}
.menu a:hover{background:var(--sand);color:var(--merlot)}
.menu .grp{padding:11px 13px 4px;font:500 10px/1 var(--bdy);letter-spacing:.18em;text-transform:uppercase;color:var(--soft)}
.hdr-cta{flex-shrink:0;margin-left:10px}
.burger,.dtog{position:absolute;opacity:0;pointer-events:none;width:0;height:0}
.burg-lbl{display:none;cursor:pointer;padding:10px;margin-left:auto;border:1px solid var(--line);background:var(--paper)}
.burg-lbl svg{width:22px;height:22px}
/* buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;padding:15px 30px;font:500 12.4px/1 var(--bdy);letter-spacing:.13em;text-transform:uppercase;text-decoration:none;border:1px solid transparent;cursor:pointer;transition:.18s;text-align:center}
.btn-p{background:var(--merlot);color:#fff}
.btn-p:hover{background:var(--merlot-d)}
.btn-s{background:transparent;color:var(--ink);border-color:var(--ink)}
.btn-s:hover{background:var(--ink);color:#fff}
.btn-w{background:transparent;color:#fff;border-color:rgba(255,255,255,.55)}
.btn-w:hover{background:#fff;color:var(--merlot)}
.btn-sm{padding:12px 22px;font-size:11.4px}
/* hero */
.hero{position:relative;background-color:var(--porcelain)}
.hero-in{display:grid;grid-template-columns:1.02fr .98fr;gap:0;align-items:stretch;min-height:min(76vh,660px)}
.hero-in>*{min-width:0}
.hero-txt{padding:clamp(44px,5.5vw,84px) clamp(24px,4vw,64px) clamp(44px,5.5vw,84px) var(--gut);display:flex;flex-direction:column;justify-content:center;max-width:760px;margin-left:auto;width:100%}
.hero h1{margin-bottom:22px}
.ans{border-left:2px solid var(--merlot);padding:4px 0 4px 20px;margin:0 0 30px;font-size:16.6px;line-height:1.72;color:#443F3B}
.hero-cta{display:flex;flex-wrap:wrap;gap:12px;margin-bottom:24px}
.hero-note{font-size:13.2px;color:var(--soft);display:flex;align-items:center;gap:9px;margin:0}
.hero-note svg{width:15px;height:15px;color:var(--merlot)}
.hero-img{position:relative}
.hero-img .ph-img{height:100%;min-height:340px}
/* strip */
.strip{background-color:var(--ink);color:#E8E3DC}
.strip-in{display:grid;grid-template-columns:repeat(4,1fr);gap:28px;padding-top:32px;padding-bottom:32px}
.strip-in>div{min-width:0}
.strip b{display:block;font-family:var(--dsp);font-size:23px;font-weight:500;color:#fff;line-height:1.25;margin-bottom:4px}
.strip span{font-size:12.9px;color:#B3ACA3;line-height:1.55;display:block}
/* layout */
.head{max-width:790px;margin-bottom:clamp(30px,3.6vw,52px)}
.head.mid{margin-left:auto;margin-right:auto;text-align:center}
.grid{display:grid;gap:clamp(16px,1.8vw,26px)}
.grid>*{min-width:0}
.g2{grid-template-columns:repeat(2,minmax(0,1fr))}
.g3{grid-template-columns:repeat(3,minmax(0,1fr))}
.g4{grid-template-columns:repeat(4,minmax(0,1fr))}
/* photo cards */
.pc{background:var(--paper);border:1px solid var(--line);display:flex;flex-direction:column;text-decoration:none;color:inherit;transition:.2s}
.pc:hover{border-color:var(--taupe);box-shadow:0 16px 40px rgba(32,32,31,.08);transform:translateY(-3px)}
.pc .ph-img{aspect-ratio:4/3}
.pc-b{padding:22px 24px 24px;display:flex;flex-direction:column;flex:1}
.pc-b h2,.pc-b h3{font-size:clamp(20px,2vw,25px);margin-bottom:9px}
.pc-b p{font-size:14.8px;color:#4E4842;margin-bottom:16px;line-height:1.66}
.go{margin-top:auto;font:500 11.4px/1 var(--bdy);letter-spacing:.14em;text-transform:uppercase;color:var(--merlot);text-decoration:none;display:inline-flex;align-items:center;gap:8px}
.go svg{width:13px;height:13px;transition:.2s}
.pc:hover .go svg,.go:hover svg{transform:translateX(4px)}
.pc-kicker{font:500 10.2px/1 var(--bdy);letter-spacing:.2em;text-transform:uppercase;color:var(--soft);margin-bottom:9px;display:block}
/* work grid */
.work .ph-img{aspect-ratio:3/3.6}
.work .cap{padding:14px 2px 0}
.work .cap b{display:block;font-family:var(--dsp);font-size:19px;font-weight:500;margin-bottom:2px}
.work .cap span{font-size:12.6px;color:var(--soft)}
/* table */
.tw{overflow-x:auto;border:1px solid var(--line);background:var(--paper)}
table{width:100%;border-collapse:collapse;font-size:14.8px;min-width:580px}
th{text-align:left;padding:15px 20px;background:var(--sand);font:500 10.6px/1.3 var(--bdy);letter-spacing:.15em;text-transform:uppercase;color:var(--soft);border-bottom:1px solid var(--line)}
td{padding:15px 20px;border-bottom:1px solid #F0E9DF;color:#4E4842;vertical-align:top}
tr:last-child td{border-bottom:0}
td b{color:var(--ink);font-weight:600}
/* steps */
.steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:clamp(18px,2.4vw,36px);counter-reset:s}
.step{min-width:0}
.step-n{counter-increment:s;font-family:var(--dsp);font-size:15px;color:var(--merlot);letter-spacing:.14em;margin-bottom:14px;display:block;padding-bottom:12px;border-bottom:1px solid var(--taupe)}
.step-n::before{content:"0" counter(s)}
.step h3{margin-bottom:7px;font-size:21px}
.step p{margin:0;font-size:14.8px;color:#4E4842;line-height:1.68}
/* cta strip */
.band{background-color:var(--merlot);color:#fff;position:relative;overflow:hidden}
.band-in{display:grid;grid-template-columns:1.25fr .75fr;gap:0;align-items:stretch}
.band-in>*{min-width:0}
.band-t{padding:clamp(46px,5.5vw,80px) clamp(28px,4vw,56px) clamp(46px,5.5vw,80px) var(--gut);display:flex;flex-direction:column;justify-content:center}
.band h2{color:#fff;font-size:clamp(28px,3.4vw,42px);margin-bottom:12px;max-width:16ch}
.band p{color:#E2CFD4;margin:0 0 26px;font-size:16px;max-width:46ch}
.band .ph-img{height:100%;min-height:240px}
/* enquiry */
.quote-in{display:grid;grid-template-columns:.9fr 1.1fr;gap:clamp(30px,4.5vw,62px);align-items:center}
.quote-in>*{min-width:0}
.qlist{list-style:none;margin:26px 0 0;padding:0}
.qlist li{display:flex;gap:12px;align-items:flex-start;margin-bottom:13px;font-size:15.2px;color:#4E4842}
.qlist svg{width:16px;height:16px;color:var(--merlot);margin-top:4px}
.fbox{background:var(--paper);border:1px solid var(--line);padding:clamp(24px,3vw,38px)}
.fbox-t{font-family:var(--dsp);font-size:clamp(22px,2.2vw,28px);font-weight:500;line-height:1.24;margin:0 0 6px}
.fbox .sm{font-size:13.4px;color:var(--soft);margin-bottom:22px}
.frow{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}
.frow>*{min-width:0}
.field{margin-bottom:15px;min-width:0}
.field label{display:block;font:500 11.4px/1 var(--bdy);letter-spacing:.1em;text-transform:uppercase;color:var(--soft);margin-bottom:8px}
.req{color:var(--merlot)}
input,select,textarea{width:100%;min-width:0;padding:13px 15px;border:1px solid var(--line);font:400 15px/1.45 var(--bdy);color:var(--ink);background:var(--paper);border-radius:0}
textarea{min-height:106px;resize:vertical}
select option{background:#fff;color:var(--ink)}
input:hover,select:hover,textarea:hover{border-color:var(--taupe)}
input:focus,select:focus,textarea:focus{border-color:var(--merlot)}
.fnote{font-size:12.4px;color:var(--soft);margin:15px 0 0;line-height:1.6}
/* footer */
footer{background-color:var(--ink);color:#B3ACA3;padding-top:clamp(48px,6vw,76px);padding-bottom:30px}
.f-top{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr 1fr;gap:34px;padding-bottom:42px;border-bottom:1px solid rgba(255,255,255,.1)}
.f-top>*{min-width:0}
.f-brand img{height:54px;width:auto;margin-bottom:22px}
.f-desc{font-size:14.2px;color:#C0B9AF;line-height:1.72;max-width:330px}
.f-tag{font-family:var(--dsp);font-size:20px;color:#fff;margin:16px 0 0;line-height:1.4}
footer h4{font:500 10.4px/1 var(--bdy);letter-spacing:.18em;text-transform:uppercase;color:#fff;margin:0 0 16px}
footer ul{list-style:none;margin:0;padding:0}
footer li{margin-bottom:10px}
footer a{color:#B3ACA3;text-decoration:none;font-size:14px;line-height:1.5}
footer a:hover{color:#fff}
.f-bot{display:flex;flex-wrap:wrap;gap:14px;justify-content:space-between;align-items:center;padding-top:26px;font-size:12.8px;color:#8A837B}
.built{display:inline-flex;align-items:center;gap:9px}
.built-ico{width:22px;height:22px}
.built b{color:var(--taupe);font-weight:600}
.pend{background:rgba(200,185,170,.13);border:1px solid rgba(200,185,170,.3);color:#D6CEC3;padding:11px 14px;font-size:12.2px;line-height:1.6;margin-top:18px}
.top{position:fixed;right:18px;bottom:18px;z-index:90;width:44px;height:44px;background:var(--merlot);color:#fff;display:flex;align-items:center;justify-content:center;text-decoration:none}
.top svg{width:18px;height:18px}
/* responsive */
@media (max-width:1240px){.nav>li>a,.drop-lbl{padding:10px 10px;font-size:13.2px}}
@media (max-width:1080px){
 .hero-in{grid-template-columns:1fr;min-height:0}
 .hero-txt{padding:clamp(38px,6vw,60px) var(--gut);max-width:none;order:2}
 .hero-img{order:1}.hero-img .ph-img{aspect-ratio:16/9;min-height:0}
 .band-in{grid-template-columns:1fr}.band-t{padding:clamp(42px,6vw,62px) var(--gut)}
 .band .ph-img{aspect-ratio:16/7;min-height:0}
 .quote-in{grid-template-columns:1fr}
 .strip-in{grid-template-columns:repeat(2,1fr);gap:24px}
 .g4,.g3{grid-template-columns:repeat(2,minmax(0,1fr))}
 .steps{grid-template-columns:repeat(2,minmax(0,1fr));gap:28px}
 .burg-lbl{display:block}.hdr-cta{display:none}
 .f-top{grid-template-columns:1.4fr 1fr 1fr;gap:28px}
 .nav{position:absolute;top:100%;left:0;right:0;flex-direction:column;align-items:stretch;background:var(--paper);border-bottom:1px solid var(--line);box-shadow:0 20px 40px rgba(32,32,31,.12);padding:8px var(--gut) 24px;max-height:0;overflow:hidden;visibility:hidden;transition:max-height .28s ease,visibility 0s .28s}
 .burger:checked ~ .nav{max-height:78vh;overflow-y:auto;visibility:visible;transition:max-height .3s ease,visibility 0s}
 .nav>li>a,.drop-lbl{padding:14px 2px;font-size:15.6px;border-bottom:1px solid #F1EAE0;justify-content:space-between}
 .menu{position:static;opacity:1;visibility:visible;transform:none;border:0;box-shadow:none;padding:0 0 6px 12px;min-width:0;max-height:0;overflow:hidden;background:transparent;transition:max-height .26s ease}
 .dtog:checked ~ .menu{max-height:760px}
 .dtog:checked ~ .drop-lbl .caret{transform:rotate(180deg)}
 .nav>li:hover>.menu,.nav>li:focus-within>.menu{opacity:1;visibility:visible}
 .mob-cta{display:block;margin-top:20px}
 .mob-cta .btn{width:100%;color:#fff;background:var(--merlot);border:1px solid var(--merlot);border-bottom:1px solid var(--merlot);justify-content:center;padding:16px 26px;font-size:12px}
 .mob-cta .btn:hover{background:var(--merlot-d);color:#fff}
}
@media (min-width:1081px){.mob-cta{display:none}}
@media (max-width:660px){
 .strip-in{grid-template-columns:1fr;gap:18px}
 .g2,.g3,.g4,.steps{grid-template-columns:1fr}
 .frow{grid-template-columns:1fr}
 .f-top{grid-template-columns:1fr;gap:28px}
 .work .ph-img{aspect-ratio:4/3}
}


:root{--pat:url('data:image/png;base64,')}

*{box-sizing:border-box}
svg{width:18px;height:18px;flex-shrink:0}
:root{
 /* Palette from the Aisle & Stem Integrated Visual Developer Guide */
 --porcelain:#F8F4ED; --merlot:#5A2B38; --taupe:#C8B9AA; --ink:#20201F;
 --merlot-d:#46212B; --merlot-l:#7A4353; --blush:#EFE3E4;
 --paper:#FFFFFF; --sand:#F2EBE1; --taupe-s:#EDE4D9; --soft:#6B6560; --line:#E3D9CC;
 --gut:clamp(18px,5vw,54px); --r:2px;
 --dsp:'EB Garamond',Georgia,'Times New Roman',serif;
 --bdy:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;
}
html{scroll-behavior:smooth}
body{margin:0;background:var(--porcelain);color:var(--ink);font:400 16px/1.72 var(--bdy);-webkit-font-smoothing:antialiased}
img{max-width:100%;display:block}
a{color:var(--merlot)}
.wrap{max-width:1280px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
h1,h2,h3{font-family:var(--dsp);font-weight:500;line-height:1.12;margin:0;letter-spacing:-.004em}
h1{font-size:clamp(34px,4.2vw,52px)}
h2{font-size:clamp(28px,3.6vw,44px)}
h3{font-size:clamp(19px,1.9vw,23px);line-height:1.3}
p{margin:0 0 16px}
.eyebrow{font:500 10.8px/1 var(--bdy);letter-spacing:.24em;text-transform:uppercase;color:var(--merlot);margin:0 0 16px;display:block}
.lede{font-size:clamp(16.5px,1.5vw,18.5px);color:#443F3B;line-height:1.7}
.sec{padding:clamp(56px,6.5vw,104px) 0}
.sec.alt{background-color:var(--paper)}
.sec.sand{background-color:var(--sand)}
.rv{animation:rvIn .85s both}
.rv2{animation-delay:.09s}.rv3{animation-delay:.18s}.rv4{animation-delay:.27s}
@keyframes rvIn{from{opacity:0;transform:translateY(22px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.rv{animation:none}}
.skip{position:absolute;left:-9999px;top:0;background:var(--merlot);color:#fff;padding:12px 18px;z-index:200}
.skip:focus{left:8px;top:8px}
a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible,label:focus-visible{outline:2.5px solid var(--merlot);outline-offset:3px}
.ph-img{width:100%;object-fit:cover;background:var(--taupe-s)}
/* interior pages */
.crumb{font:400 12.6px/1.6 var(--bdy);color:var(--soft);padding-top:20px}
.crumb a{color:var(--soft);text-decoration:none}
.crumb a:hover{color:var(--merlot)}
.crumb span{color:var(--taupe);margin:0 7px}
.crumb b{color:var(--ink);font-weight:500}
.sub{background-color:var(--porcelain);border-bottom:1px solid var(--line)}
.sub-in{display:grid;grid-template-columns:1.08fr .92fr;gap:clamp(28px,4vw,60px);align-items:center;
 padding-top:clamp(30px,3.6vw,52px);padding-bottom:clamp(40px,4.6vw,68px)}
.sub-in>*{min-width:0}
.sub h1{margin-bottom:20px}
.sub .ph-img{aspect-ratio:4/3}
.sub-solo{max-width:840px;padding-top:clamp(28px,3.4vw,46px);padding-bottom:clamp(40px,4.6vw,66px)}
.prose{max-width:820px}
.prose h2{margin-top:clamp(36px,4vw,58px);margin-bottom:14px}
.prose h2:first-child{margin-top:0}
.prose h3{margin-top:30px;margin-bottom:10px}
.prose p{font-size:16.4px;line-height:1.78;color:#443F3B}
.prose ul.b{list-style:none;margin:14px 0 20px;padding:0}
.prose ul.b li{position:relative;padding-left:24px;margin-bottom:10px;font-size:16px;line-height:1.72;color:#443F3B}
.prose ul.b li::before{content:"";position:absolute;left:2px;top:11px;width:7px;height:7px;border:1px solid var(--merlot);transform:rotate(45deg)}
.prose .tw{margin:20px 0 8px}
.note{background-color:var(--sand);border-left:2px solid var(--merlot);padding:18px 22px;margin:22px 0;font-size:15.4px;line-height:1.7;color:#443F3B}
.note b{color:var(--ink)}
.faq{max-width:820px;margin-top:clamp(30px,3.4vw,44px)}
.glist{display:grid;gap:16px}
.gl{display:grid;grid-template-columns:1fr 220px;gap:24px;align-items:center;background-color:var(--paper);border:1px solid var(--line);padding:clamp(22px,2.6vw,34px);text-decoration:none;transition:border-color .2s,transform .2s}
.gl:hover{border-color:var(--merlot);transform:translateY(-2px)}
.gl h3{font-family:var(--dsp);font-size:clamp(21px,2.1vw,26px);font-weight:500;color:var(--ink);margin:10px 0 8px;line-height:1.25}
.gl p{font-size:15px;color:var(--soft);line-height:1.65;margin:0 0 14px;max-width:62ch}
.gl .tag{display:inline-block;font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--merlot);font-weight:600}
.gl-r{font-size:13px;color:var(--soft);text-align:right;border-left:1px solid var(--line);padding-left:24px}
.gl-r b{display:block;color:var(--ink);font-weight:500;margin-top:4px}
@media (max-width:820px){.gl{grid-template-columns:1fr;gap:14px}.gl-r{text-align:left;border-left:0;border-top:1px solid var(--line);padding:14px 0 0}}
.prose p.upd{font-size:13px;color:var(--soft);border-left:2px solid var(--taupe);padding-left:14px;margin-top:26px;font-style:italic}
details{border-bottom:1px solid var(--line)}
summary{padding:18px 2px;cursor:pointer;font:500 16.4px/1.5 var(--bdy);color:var(--ink);list-style:none;display:flex;justify-content:space-between;gap:18px;align-items:flex-start}
summary::-webkit-details-marker{display:none}
summary::after{content:"";width:9px;height:9px;border-right:1.6px solid var(--merlot);border-bottom:1.6px solid var(--merlot);transform:rotate(45deg);flex-shrink:0;margin-top:7px;transition:.2s}
details[open] summary::after{transform:rotate(-135deg)}
details .a{padding:0 2px 20px;font-size:15.6px;color:#443F3B;line-height:1.76;max-width:74ch}
details .a p:last-child{margin-bottom:0}
.side{background-color:var(--paper);border:1px solid var(--line);padding:24px 26px;position:sticky;top:96px}
.side h3{font-size:20px;margin-bottom:12px}
.side ul{list-style:none;margin:0;padding:0}
.side li{border-bottom:1px solid #F1EAE0}
.side li:last-child{border-bottom:0}
.side a{display:block;padding:11px 0;font-size:14.8px;color:#443F3B;text-decoration:none}
.side a:hover{color:var(--merlot)}
.split{display:grid;grid-template-columns:1fr 320px;gap:clamp(30px,4vw,56px);align-items:start}
.split>*{min-width:0}
@media (max-width:1080px){.sub-in{grid-template-columns:1fr}.sub .shot{order:-1}.split{grid-template-columns:1fr}
.side{position:static;top:auto}}
/* botanical watermark, opacity baked into the PNG so no pseudo-element or z-index is needed */
.wm{background-image:var(--pat);background-repeat:repeat;background-size:440px 440px;background-position:center top}
@media (max-width:700px){.wm{background-size:300px 300px}}

/* header */
header{position:sticky;top:0;z-index:120;background:rgba(248,244,237,.95);backdrop-filter:saturate(1.3) blur(10px);border-bottom:1px solid var(--line)}
.hdr-in{max-width:1280px;margin:0 auto;padding:0 var(--gut);display:flex;align-items:center;gap:18px;min-height:94px}
.brand{display:flex;align-items:center;flex-shrink:0;margin-right:auto}
.brand img{height:50px;width:auto}
.nav{display:flex;align-items:center;gap:0;list-style:none;margin:0;padding:0}
.nav>li{position:relative}
.nav>li>a,.drop-lbl{display:flex;align-items:center;gap:5px;padding:10px 13px;font:400 13.8px/1 var(--bdy);letter-spacing:.02em;color:var(--ink);text-decoration:none;cursor:pointer;white-space:nowrap}
.nav>li>a:hover,.drop-lbl:hover{color:var(--merlot)}
.caret{width:10px;height:10px;transition:transform .2s;opacity:.55}
.menu{position:absolute;top:calc(100% + 6px);left:0;min-width:272px;background:var(--paper);border:1px solid var(--line);padding:8px;box-shadow:0 22px 50px rgba(32,32,31,.13);list-style:none;margin:0;opacity:0;visibility:hidden;transform:translateY(-6px);transition:.16s}
.nav>li:hover>.menu,.nav>li:focus-within>.menu{opacity:1;visibility:visible;transform:none}
.menu a{display:block;padding:9px 13px;font:400 13.9px/1.45 var(--bdy);color:#443F3B;text-decoration:none}
.menu a:hover{background:var(--sand);color:var(--merlot)}
.menu .grp{padding:11px 13px 4px;font:500 10px/1 var(--bdy);letter-spacing:.18em;text-transform:uppercase;color:var(--soft)}
.hdr-cta{flex-shrink:0;margin-left:10px}
.burger,.dtog{position:absolute;opacity:0;pointer-events:none;width:0;height:0}
.burg-lbl{display:none;cursor:pointer;padding:10px;margin-left:auto;border:1px solid var(--line);background:var(--paper)}
.burg-lbl svg{width:22px;height:22px}
/* buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;padding:15px 30px;font:500 12.4px/1 var(--bdy);letter-spacing:.13em;text-transform:uppercase;text-decoration:none;border:1px solid transparent;cursor:pointer;transition:.18s;text-align:center}
.btn-p{background:var(--merlot);color:#fff}
.btn-p:hover{background:var(--merlot-d)}
.btn-s{background:transparent;color:var(--ink);border-color:var(--ink)}
.btn-s:hover{background:var(--ink);color:#fff}
.btn-w{background:transparent;color:#fff;border-color:rgba(255,255,255,.55)}
.btn-w:hover{background:#fff;color:var(--merlot)}
.btn-sm{padding:12px 22px;font-size:11.4px}
/* hero */
.hero{position:relative;background-color:var(--porcelain)}
.hero-in{display:grid;grid-template-columns:1.02fr .98fr;gap:0;align-items:stretch;min-height:min(76vh,660px)}
.hero-in>*{min-width:0}
.hero-txt{padding:clamp(44px,5.5vw,84px) clamp(24px,4vw,64px) clamp(44px,5.5vw,84px) var(--gut);display:flex;flex-direction:column;justify-content:center;max-width:760px;margin-left:auto;width:100%}
.hero h1{margin-bottom:22px}
.ans{border-left:2px solid var(--merlot);padding:4px 0 4px 20px;margin:0 0 30px;font-size:16.6px;line-height:1.72;color:#443F3B}
.hero-cta{display:flex;flex-wrap:wrap;gap:12px;margin-bottom:24px}
.hero-note{font-size:13.2px;color:var(--soft);display:flex;align-items:center;gap:9px;margin:0}
.hero-note svg{width:15px;height:15px;color:var(--merlot)}
.hero-img{position:relative}
.hero-img .ph-img{height:100%;min-height:340px}
/* strip */
.strip{background-color:var(--ink);color:#E8E3DC}
.strip-in{display:grid;grid-template-columns:repeat(4,1fr);gap:28px;padding-top:32px;padding-bottom:32px}
.strip-in>div{min-width:0}
.strip b{display:block;font-family:var(--dsp);font-size:23px;font-weight:500;color:#fff;line-height:1.25;margin-bottom:4px}
.strip span{font-size:12.9px;color:#B3ACA3;line-height:1.55;display:block}
/* layout */
.head{max-width:790px;margin-bottom:clamp(30px,3.6vw,52px)}
.head.mid{margin-left:auto;margin-right:auto;text-align:center}
.grid{display:grid;gap:clamp(16px,1.8vw,26px)}
.grid>*{min-width:0}
.g2{grid-template-columns:repeat(2,minmax(0,1fr))}
.g3{grid-template-columns:repeat(3,minmax(0,1fr))}
.g4{grid-template-columns:repeat(4,minmax(0,1fr))}
/* photo cards */
.pc{background:var(--paper);border:1px solid var(--line);display:flex;flex-direction:column;text-decoration:none;color:inherit;transition:.2s}
.pc:hover{border-color:var(--taupe);box-shadow:0 16px 40px rgba(32,32,31,.08);transform:translateY(-3px)}
.pc .ph-img{aspect-ratio:4/3}
.pc-b{padding:22px 24px 24px;display:flex;flex-direction:column;flex:1}
.pc-b h2,.pc-b h3{font-size:clamp(20px,2vw,25px);margin-bottom:9px}
.pc-b p{font-size:14.8px;color:#4E4842;margin-bottom:16px;line-height:1.66}
.go{margin-top:auto;font:500 11.4px/1 var(--bdy);letter-spacing:.14em;text-transform:uppercase;color:var(--merlot);text-decoration:none;display:inline-flex;align-items:center;gap:8px}
.go svg{width:13px;height:13px;transition:.2s}
.pc:hover .go svg,.go:hover svg{transform:translateX(4px)}
.pc-kicker{font:500 10.2px/1 var(--bdy);letter-spacing:.2em;text-transform:uppercase;color:var(--soft);margin-bottom:9px;display:block}
/* work grid */
.work .ph-img{aspect-ratio:3/3.6}
.work .cap{padding:14px 2px 0}
.work .cap b{display:block;font-family:var(--dsp);font-size:19px;font-weight:500;margin-bottom:2px}
.work .cap span{font-size:12.6px;color:var(--soft)}
/* table */
.tw{overflow-x:auto;border:1px solid var(--line);background:var(--paper)}
table{width:100%;border-collapse:collapse;font-size:14.8px;min-width:580px}
th{text-align:left;padding:15px 20px;background:var(--sand);font:500 10.6px/1.3 var(--bdy);letter-spacing:.15em;text-transform:uppercase;color:var(--soft);border-bottom:1px solid var(--line)}
td{padding:15px 20px;border-bottom:1px solid #F0E9DF;color:#4E4842;vertical-align:top}
tr:last-child td{border-bottom:0}
td b{color:var(--ink);font-weight:600}
/* steps */
.steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:clamp(18px,2.4vw,36px);counter-reset:s}
.step{min-width:0}
.step-n{counter-increment:s;font-family:var(--dsp);font-size:15px;color:var(--merlot);letter-spacing:.14em;margin-bottom:14px;display:block;padding-bottom:12px;border-bottom:1px solid var(--taupe)}
.step-n::before{content:"0" counter(s)}
.step h3{margin-bottom:7px;font-size:21px}
.step p{margin:0;font-size:14.8px;color:#4E4842;line-height:1.68}
/* cta strip */
.band{background-color:var(--merlot);color:#fff;position:relative;overflow:hidden}
.band-in{display:grid;grid-template-columns:1.25fr .75fr;gap:0;align-items:stretch}
.band-in>*{min-width:0}
.band-t{padding:clamp(46px,5.5vw,80px) clamp(28px,4vw,56px) clamp(46px,5.5vw,80px) var(--gut);display:flex;flex-direction:column;justify-content:center}
.band h2{color:#fff;font-size:clamp(28px,3.4vw,42px);margin-bottom:12px;max-width:16ch}
.band p{color:#E2CFD4;margin:0 0 26px;font-size:16px;max-width:46ch}
.band .ph-img{height:100%;min-height:240px}
/* enquiry */
.quote-in{display:grid;grid-template-columns:.9fr 1.1fr;gap:clamp(30px,4.5vw,62px);align-items:center}
.quote-in>*{min-width:0}
.qlist{list-style:none;margin:26px 0 0;padding:0}
.qlist li{display:flex;gap:12px;align-items:flex-start;margin-bottom:13px;font-size:15.2px;color:#4E4842}
.qlist svg{width:16px;height:16px;color:var(--merlot);margin-top:4px}
.fbox{background:var(--paper);border:1px solid var(--line);padding:clamp(24px,3vw,38px)}
.fbox-t{font-family:var(--dsp);font-size:clamp(22px,2.2vw,28px);font-weight:500;line-height:1.24;margin:0 0 6px}
.fbox .sm{font-size:13.4px;color:var(--soft);margin-bottom:22px}
.frow{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}
.frow>*{min-width:0}
.field{margin-bottom:15px;min-width:0}
.field label{display:block;font:500 11.4px/1 var(--bdy);letter-spacing:.1em;text-transform:uppercase;color:var(--soft);margin-bottom:8px}
.req{color:var(--merlot)}
input,select,textarea{width:100%;min-width:0;padding:13px 15px;border:1px solid var(--line);font:400 15px/1.45 var(--bdy);color:var(--ink);background:var(--paper);border-radius:0}
textarea{min-height:106px;resize:vertical}
select option{background:#fff;color:var(--ink)}
input:hover,select:hover,textarea:hover{border-color:var(--taupe)}
input:focus,select:focus,textarea:focus{border-color:var(--merlot)}
.fnote{font-size:12.4px;color:var(--soft);margin:15px 0 0;line-height:1.6}
/* footer */
footer{background-color:var(--ink);color:#B3ACA3;padding-top:clamp(48px,6vw,76px);padding-bottom:30px}
.f-top{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr 1fr;gap:34px;padding-bottom:42px;border-bottom:1px solid rgba(255,255,255,.1)}
.f-top>*{min-width:0}
.f-brand img{height:54px;width:auto;margin-bottom:22px}
.f-desc{font-size:14.2px;color:#C0B9AF;line-height:1.72;max-width:330px}
.f-tag{font-family:var(--dsp);font-size:20px;color:#fff;margin:16px 0 0;line-height:1.4}
footer h4{font:500 10.4px/1 var(--bdy);letter-spacing:.18em;text-transform:uppercase;color:#fff;margin:0 0 16px}
footer ul{list-style:none;margin:0;padding:0}
footer li{margin-bottom:10px}
footer a{color:#B3ACA3;text-decoration:none;font-size:14px;line-height:1.5}
footer a:hover{color:#fff}
.f-bot{display:flex;flex-wrap:wrap;gap:14px;justify-content:space-between;align-items:center;padding-top:26px;font-size:12.8px;color:#8A837B}
.built{display:inline-flex;align-items:center;gap:9px}
.built-ico{width:22px;height:22px}
.built b{color:var(--taupe);font-weight:600}
.pend{background:rgba(200,185,170,.13);border:1px solid rgba(200,185,170,.3);color:#D6CEC3;padding:11px 14px;font-size:12.2px;line-height:1.6;margin-top:18px}
.top{position:fixed;right:18px;bottom:18px;z-index:90;width:44px;height:44px;background:var(--merlot);color:#fff;display:flex;align-items:center;justify-content:center;text-decoration:none}
.top svg{width:18px;height:18px}
/* responsive */
@media (max-width:1240px){.nav>li>a,.drop-lbl{padding:10px 10px;font-size:13.2px}}
@media (max-width:1080px){
 .hero-in{grid-template-columns:1fr;min-height:0}
 .hero-txt{padding:clamp(38px,6vw,60px) var(--gut);max-width:none;order:2}
 .hero-img{order:1}.hero-img .ph-img{aspect-ratio:16/9;min-height:0}
 .band-in{grid-template-columns:1fr}.band-t{padding:clamp(42px,6vw,62px) var(--gut)}
 .band .ph-img{aspect-ratio:16/7;min-height:0}
 .quote-in{grid-template-columns:1fr}
 .strip-in{grid-template-columns:repeat(2,1fr);gap:24px}
 .g4,.g3{grid-template-columns:repeat(2,minmax(0,1fr))}
 .steps{grid-template-columns:repeat(2,minmax(0,1fr));gap:28px}
 .burg-lbl{display:block}.hdr-cta{display:none}
 .f-top{grid-template-columns:1.4fr 1fr 1fr;gap:28px}
 .nav{position:absolute;top:100%;left:0;right:0;flex-direction:column;align-items:stretch;background:var(--paper);border-bottom:1px solid var(--line);box-shadow:0 20px 40px rgba(32,32,31,.12);padding:8px var(--gut) 24px;max-height:0;overflow:hidden;visibility:hidden;transition:max-height .28s ease,visibility 0s .28s}
 .burger:checked ~ .nav{max-height:78vh;overflow-y:auto;visibility:visible;transition:max-height .3s ease,visibility 0s}
 .nav>li>a,.drop-lbl{padding:14px 2px;font-size:15.6px;border-bottom:1px solid #F1EAE0;justify-content:space-between}
 .menu{position:static;opacity:1;visibility:visible;transform:none;border:0;box-shadow:none;padding:0 0 6px 12px;min-width:0;max-height:0;overflow:hidden;background:transparent;transition:max-height .26s ease}
 .dtog:checked ~ .menu{max-height:760px}
 .dtog:checked ~ .drop-lbl .caret{transform:rotate(180deg)}
 .nav>li:hover>.menu,.nav>li:focus-within>.menu{opacity:1;visibility:visible}
 .mob-cta{display:block;margin-top:20px}
 .mob-cta .btn{width:100%;color:#fff;background:var(--merlot);border:1px solid var(--merlot);border-bottom:1px solid var(--merlot);justify-content:center;padding:16px 26px;font-size:12px}
 .mob-cta .btn:hover{background:var(--merlot-d);color:#fff}
}
@media (min-width:1081px){.mob-cta{display:none}}
@media (max-width:660px){
 .strip-in{grid-template-columns:1fr;gap:18px}
 .g2,.g3,.g4,.steps{grid-template-columns:1fr}
 .frow{grid-template-columns:1fr}
 .f-top{grid-template-columns:1fr;gap:28px}
 .work .ph-img{aspect-ratio:4/3}
}


:root{--pat:url('data:image/png;base64,')}

*{box-sizing:border-box}
svg{width:18px;height:18px;flex-shrink:0}
:root{
 /* Palette from the Aisle & Stem Integrated Visual Developer Guide */
 --porcelain:#F8F4ED; --merlot:#5A2B38; --taupe:#C8B9AA; --ink:#20201F;
 --merlot-d:#46212B; --merlot-l:#7A4353; --blush:#EFE3E4;
 --paper:#FFFFFF; --sand:#F2EBE1; --taupe-s:#EDE4D9; --soft:#6B6560; --line:#E3D9CC;
 --gut:clamp(18px,5vw,54px); --r:2px;
 --dsp:'EB Garamond',Georgia,'Times New Roman',serif;
 --bdy:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;
}
html{scroll-behavior:smooth}
body{margin:0;background:var(--porcelain);color:var(--ink);font:400 16px/1.72 var(--bdy);-webkit-font-smoothing:antialiased}
img{max-width:100%;display:block}
a{color:var(--merlot)}
.wrap{max-width:1280px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
h1,h2,h3{font-family:var(--dsp);font-weight:500;line-height:1.12;margin:0;letter-spacing:-.004em}
h1{font-size:clamp(34px,4.2vw,52px)}
h2{font-size:clamp(28px,3.6vw,44px)}
h3{font-size:clamp(19px,1.9vw,23px);line-height:1.3}
p{margin:0 0 16px}
.eyebrow{font:500 10.8px/1 var(--bdy);letter-spacing:.24em;text-transform:uppercase;color:var(--merlot);margin:0 0 16px;display:block}
.lede{font-size:clamp(16.5px,1.5vw,18.5px);color:#443F3B;line-height:1.7}
.sec{padding:clamp(56px,6.5vw,104px) 0}
.sec.alt{background-color:var(--paper)}
.sec.sand{background-color:var(--sand)}
.rv{animation:rvIn .85s both}
.rv2{animation-delay:.09s}.rv3{animation-delay:.18s}.rv4{animation-delay:.27s}
@keyframes rvIn{from{opacity:0;transform:translateY(22px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.rv{animation:none}}
.skip{position:absolute;left:-9999px;top:0;background:var(--merlot);color:#fff;padding:12px 18px;z-index:200}
.skip:focus{left:8px;top:8px}
a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible,label:focus-visible{outline:2.5px solid var(--merlot);outline-offset:3px}
.ph-img{width:100%;object-fit:cover;background:var(--taupe-s)}
/* interior pages */
.crumb{font:400 12.6px/1.6 var(--bdy);color:var(--soft);padding-top:20px}
.crumb a{color:var(--soft);text-decoration:none}
.crumb a:hover{color:var(--merlot)}
.crumb span{color:var(--taupe);margin:0 7px}
.crumb b{color:var(--ink);font-weight:500}
.sub{background-color:var(--porcelain);border-bottom:1px solid var(--line)}
.sub-in{display:grid;grid-template-columns:1.08fr .92fr;gap:clamp(28px,4vw,60px);align-items:center;
 padding-top:clamp(30px,3.6vw,52px);padding-bottom:clamp(40px,4.6vw,68px)}
.sub-in>*{min-width:0}
.sub h1{margin-bottom:20px}
.sub .ph-img{aspect-ratio:4/3}
.sub-solo{max-width:840px;padding-top:clamp(28px,3.4vw,46px);padding-bottom:clamp(40px,4.6vw,66px)}
.prose{max-width:820px}
.prose h2{margin-top:clamp(36px,4vw,58px);margin-bottom:14px}
.prose h2:first-child{margin-top:0}
.prose h3{margin-top:30px;margin-bottom:10px}
.prose p{font-size:16.4px;line-height:1.78;color:#443F3B}
.prose ul.b{list-style:none;margin:14px 0 20px;padding:0}
.prose ul.b li{position:relative;padding-left:24px;margin-bottom:10px;font-size:16px;line-height:1.72;color:#443F3B}
.prose ul.b li::before{content:"";position:absolute;left:2px;top:11px;width:7px;height:7px;border:1px solid var(--merlot);transform:rotate(45deg)}
.prose .tw{margin:20px 0 8px}
.note{background-color:var(--sand);border-left:2px solid var(--merlot);padding:18px 22px;margin:22px 0;font-size:15.4px;line-height:1.7;color:#443F3B}
.note b{color:var(--ink)}
.faq{max-width:820px;margin-top:clamp(30px,3.4vw,44px)}
.glist{display:grid;gap:16px}
.gl{display:grid;grid-template-columns:1fr 220px;gap:24px;align-items:center;background-color:var(--paper);border:1px solid var(--line);padding:clamp(22px,2.6vw,34px);text-decoration:none;transition:border-color .2s,transform .2s}
.gl:hover{border-color:var(--merlot);transform:translateY(-2px)}
.gl h3{font-family:var(--dsp);font-size:clamp(21px,2.1vw,26px);font-weight:500;color:var(--ink);margin:10px 0 8px;line-height:1.25}
.gl p{font-size:15px;color:var(--soft);line-height:1.65;margin:0 0 14px;max-width:62ch}
.gl .tag{display:inline-block;font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--merlot);font-weight:600}
.gl-r{font-size:13px;color:var(--soft);text-align:right;border-left:1px solid var(--line);padding-left:24px}
.gl-r b{display:block;color:var(--ink);font-weight:500;margin-top:4px}
@media (max-width:820px){.gl{grid-template-columns:1fr;gap:14px}.gl-r{text-align:left;border-left:0;border-top:1px solid var(--line);padding:14px 0 0}}
.prose p.upd{font-size:13px;color:var(--soft);border-left:2px solid var(--taupe);padding-left:14px;margin-top:26px;font-style:italic}
details{border-bottom:1px solid var(--line)}
summary{padding:18px 2px;cursor:pointer;font:500 16.4px/1.5 var(--bdy);color:var(--ink);list-style:none;display:flex;justify-content:space-between;gap:18px;align-items:flex-start}
summary::-webkit-details-marker{display:none}
summary::after{content:"";width:9px;height:9px;border-right:1.6px solid var(--merlot);border-bottom:1.6px solid var(--merlot);transform:rotate(45deg);flex-shrink:0;margin-top:7px;transition:.2s}
details[open] summary::after{transform:rotate(-135deg)}
details .a{padding:0 2px 20px;font-size:15.6px;color:#443F3B;line-height:1.76;max-width:74ch}
details .a p:last-child{margin-bottom:0}
.side{background-color:var(--paper);border:1px solid var(--line);padding:24px 26px;position:sticky;top:96px}
.side h3{font-size:20px;margin-bottom:12px}
.side ul{list-style:none;margin:0;padding:0}
.side li{border-bottom:1px solid #F1EAE0}
.side li:last-child{border-bottom:0}
.side a{display:block;padding:11px 0;font-size:14.8px;color:#443F3B;text-decoration:none}
.side a:hover{color:var(--merlot)}
.split{display:grid;grid-template-columns:1fr 320px;gap:clamp(30px,4vw,56px);align-items:start}
.split>*{min-width:0}
@media (max-width:1080px){.sub-in{grid-template-columns:1fr}.sub .shot{order:-1}.split{grid-template-columns:1fr}
.side{position:static;top:auto}}
/* botanical watermark, opacity baked into the PNG so no pseudo-element or z-index is needed */
.wm{background-image:var(--pat);background-repeat:repeat;background-size:440px 440px;background-position:center top}
@media (max-width:700px){.wm{background-size:300px 300px}}

/* header */
header{position:sticky;top:0;z-index:120;background:rgba(248,244,237,.95);backdrop-filter:saturate(1.3) blur(10px);border-bottom:1px solid var(--line)}
.hdr-in{max-width:1280px;margin:0 auto;padding:0 var(--gut);display:flex;align-items:center;gap:18px;min-height:94px}
.brand{display:flex;align-items:center;flex-shrink:0;margin-right:auto}
.brand img{height:50px;width:auto}
.nav{display:flex;align-items:center;gap:0;list-style:none;margin:0;padding:0}
.nav>li{position:relative}
.nav>li>a,.drop-lbl{display:flex;align-items:center;gap:5px;padding:10px 13px;font:400 13.8px/1 var(--bdy);letter-spacing:.02em;color:var(--ink);text-decoration:none;cursor:pointer;white-space:nowrap}
.nav>li>a:hover,.drop-lbl:hover{color:var(--merlot)}
.caret{width:10px;height:10px;transition:transform .2s;opacity:.55}
.menu{position:absolute;top:calc(100% + 6px);left:0;min-width:272px;background:var(--paper);border:1px solid var(--line);padding:8px;box-shadow:0 22px 50px rgba(32,32,31,.13);list-style:none;margin:0;opacity:0;visibility:hidden;transform:translateY(-6px);transition:.16s}
.nav>li:hover>.menu,.nav>li:focus-within>.menu{opacity:1;visibility:visible;transform:none}
.menu a{display:block;padding:9px 13px;font:400 13.9px/1.45 var(--bdy);color:#443F3B;text-decoration:none}
.menu a:hover{background:var(--sand);color:var(--merlot)}
.menu .grp{padding:11px 13px 4px;font:500 10px/1 var(--bdy);letter-spacing:.18em;text-transform:uppercase;color:var(--soft)}
.hdr-cta{flex-shrink:0;margin-left:10px}
.burger,.dtog{position:absolute;opacity:0;pointer-events:none;width:0;height:0}
.burg-lbl{display:none;cursor:pointer;padding:10px;margin-left:auto;border:1px solid var(--line);background:var(--paper)}
.burg-lbl svg{width:22px;height:22px}
/* buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;padding:15px 30px;font:500 12.4px/1 var(--bdy);letter-spacing:.13em;text-transform:uppercase;text-decoration:none;border:1px solid transparent;cursor:pointer;transition:.18s;text-align:center}
.btn-p{background:var(--merlot);color:#fff}
.btn-p:hover{background:var(--merlot-d)}
.btn-s{background:transparent;color:var(--ink);border-color:var(--ink)}
.btn-s:hover{background:var(--ink);color:#fff}
.btn-w{background:transparent;color:#fff;border-color:rgba(255,255,255,.55)}
.btn-w:hover{background:#fff;color:var(--merlot)}
.btn-sm{padding:12px 22px;font-size:11.4px}
/* hero */
.hero{position:relative;background-color:var(--porcelain)}
.hero-in{display:grid;grid-template-columns:1.02fr .98fr;gap:0;align-items:stretch;min-height:min(76vh,660px)}
.hero-in>*{min-width:0}
.hero-txt{padding:clamp(44px,5.5vw,84px) clamp(24px,4vw,64px) clamp(44px,5.5vw,84px) var(--gut);display:flex;flex-direction:column;justify-content:center;max-width:760px;margin-left:auto;width:100%}
.hero h1{margin-bottom:22px}
.ans{border-left:2px solid var(--merlot);padding:4px 0 4px 20px;margin:0 0 30px;font-size:16.6px;line-height:1.72;color:#443F3B}
.hero-cta{display:flex;flex-wrap:wrap;gap:12px;margin-bottom:24px}
.hero-note{font-size:13.2px;color:var(--soft);display:flex;align-items:center;gap:9px;margin:0}
.hero-note svg{width:15px;height:15px;color:var(--merlot)}
.hero-img{position:relative}
.hero-img .ph-img{height:100%;min-height:340px}
/* strip */
.strip{background-color:var(--ink);color:#E8E3DC}
.strip-in{display:grid;grid-template-columns:repeat(4,1fr);gap:28px;padding-top:32px;padding-bottom:32px}
.strip-in>div{min-width:0}
.strip b{display:block;font-family:var(--dsp);font-size:23px;font-weight:500;color:#fff;line-height:1.25;margin-bottom:4px}
.strip span{font-size:12.9px;color:#B3ACA3;line-height:1.55;display:block}
/* layout */
.head{max-width:790px;margin-bottom:clamp(30px,3.6vw,52px)}
.head.mid{margin-left:auto;margin-right:auto;text-align:center}
.grid{display:grid;gap:clamp(16px,1.8vw,26px)}
.grid>*{min-width:0}
.g2{grid-template-columns:repeat(2,minmax(0,1fr))}
.g3{grid-template-columns:repeat(3,minmax(0,1fr))}
.g4{grid-template-columns:repeat(4,minmax(0,1fr))}
/* photo cards */
.pc{background:var(--paper);border:1px solid var(--line);display:flex;flex-direction:column;text-decoration:none;color:inherit;transition:.2s}
.pc:hover{border-color:var(--taupe);box-shadow:0 16px 40px rgba(32,32,31,.08);transform:translateY(-3px)}
.pc .ph-img{aspect-ratio:4/3}
.pc-b{padding:22px 24px 24px;display:flex;flex-direction:column;flex:1}
.pc-b h2,.pc-b h3{font-size:clamp(20px,2vw,25px);margin-bottom:9px}
.pc-b p{font-size:14.8px;color:#4E4842;margin-bottom:16px;line-height:1.66}
.go{margin-top:auto;font:500 11.4px/1 var(--bdy);letter-spacing:.14em;text-transform:uppercase;color:var(--merlot);text-decoration:none;display:inline-flex;align-items:center;gap:8px}
.go svg{width:13px;height:13px;transition:.2s}
.pc:hover .go svg,.go:hover svg{transform:translateX(4px)}
.pc-kicker{font:500 10.2px/1 var(--bdy);letter-spacing:.2em;text-transform:uppercase;color:var(--soft);margin-bottom:9px;display:block}
/* work grid */
.work .ph-img{aspect-ratio:3/3.6}
.work .cap{padding:14px 2px 0}
.work .cap b{display:block;font-family:var(--dsp);font-size:19px;font-weight:500;margin-bottom:2px}
.work .cap span{font-size:12.6px;color:var(--soft)}
/* table */
.tw{overflow-x:auto;border:1px solid var(--line);background:var(--paper)}
table{width:100%;border-collapse:collapse;font-size:14.8px;min-width:580px}
th{text-align:left;padding:15px 20px;background:var(--sand);font:500 10.6px/1.3 var(--bdy);letter-spacing:.15em;text-transform:uppercase;color:var(--soft);border-bottom:1px solid var(--line)}
td{padding:15px 20px;border-bottom:1px solid #F0E9DF;color:#4E4842;vertical-align:top}
tr:last-child td{border-bottom:0}
td b{color:var(--ink);font-weight:600}
/* steps */
.steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:clamp(18px,2.4vw,36px);counter-reset:s}
.step{min-width:0}
.step-n{counter-increment:s;font-family:var(--dsp);font-size:15px;color:var(--merlot);letter-spacing:.14em;margin-bottom:14px;display:block;padding-bottom:12px;border-bottom:1px solid var(--taupe)}
.step-n::before{content:"0" counter(s)}
.step h3{margin-bottom:7px;font-size:21px}
.step p{margin:0;font-size:14.8px;color:#4E4842;line-height:1.68}
/* cta strip */
.band{background-color:var(--merlot);color:#fff;position:relative;overflow:hidden}
.band-in{display:grid;grid-template-columns:1.25fr .75fr;gap:0;align-items:stretch}
.band-in>*{min-width:0}
.band-t{padding:clamp(46px,5.5vw,80px) clamp(28px,4vw,56px) clamp(46px,5.5vw,80px) var(--gut);display:flex;flex-direction:column;justify-content:center}
.band h2{color:#fff;font-size:clamp(28px,3.4vw,42px);margin-bottom:12px;max-width:16ch}
.band p{color:#E2CFD4;margin:0 0 26px;font-size:16px;max-width:46ch}
.band .ph-img{height:100%;min-height:240px}
/* enquiry */
.quote-in{display:grid;grid-template-columns:.9fr 1.1fr;gap:clamp(30px,4.5vw,62px);align-items:center}
.quote-in>*{min-width:0}
.qlist{list-style:none;margin:26px 0 0;padding:0}
.qlist li{display:flex;gap:12px;align-items:flex-start;margin-bottom:13px;font-size:15.2px;color:#4E4842}
.qlist svg{width:16px;height:16px;color:var(--merlot);margin-top:4px}
.fbox{background:var(--paper);border:1px solid var(--line);padding:clamp(24px,3vw,38px)}
.fbox-t{font-family:var(--dsp);font-size:clamp(22px,2.2vw,28px);font-weight:500;line-height:1.24;margin:0 0 6px}
.fbox .sm{font-size:13.4px;color:var(--soft);margin-bottom:22px}
.frow{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}
.frow>*{min-width:0}
.field{margin-bottom:15px;min-width:0}
.field label{display:block;font:500 11.4px/1 var(--bdy);letter-spacing:.1em;text-transform:uppercase;color:var(--soft);margin-bottom:8px}
.req{color:var(--merlot)}
input,select,textarea{width:100%;min-width:0;padding:13px 15px;border:1px solid var(--line);font:400 15px/1.45 var(--bdy);color:var(--ink);background:var(--paper);border-radius:0}
textarea{min-height:106px;resize:vertical}
select option{background:#fff;color:var(--ink)}
input:hover,select:hover,textarea:hover{border-color:var(--taupe)}
input:focus,select:focus,textarea:focus{border-color:var(--merlot)}
.fnote{font-size:12.4px;color:var(--soft);margin:15px 0 0;line-height:1.6}
/* footer */
footer{background-color:var(--ink);color:#B3ACA3;padding-top:clamp(48px,6vw,76px);padding-bottom:30px}
.f-top{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr 1fr;gap:34px;padding-bottom:42px;border-bottom:1px solid rgba(255,255,255,.1)}
.f-top>*{min-width:0}
.f-brand img{height:54px;width:auto;margin-bottom:22px}
.f-desc{font-size:14.2px;color:#C0B9AF;line-height:1.72;max-width:330px}
.f-tag{font-family:var(--dsp);font-size:20px;color:#fff;margin:16px 0 0;line-height:1.4}
footer h4{font:500 10.4px/1 var(--bdy);letter-spacing:.18em;text-transform:uppercase;color:#fff;margin:0 0 16px}
footer ul{list-style:none;margin:0;padding:0}
footer li{margin-bottom:10px}
footer a{color:#B3ACA3;text-decoration:none;font-size:14px;line-height:1.5}
footer a:hover{color:#fff}
.f-bot{display:flex;flex-wrap:wrap;gap:14px;justify-content:space-between;align-items:center;padding-top:26px;font-size:12.8px;color:#8A837B}
.built{display:inline-flex;align-items:center;gap:9px}
.built-ico{width:22px;height:22px}
.built b{color:var(--taupe);font-weight:600}
.pend{background:rgba(200,185,170,.13);border:1px solid rgba(200,185,170,.3);color:#D6CEC3;padding:11px 14px;font-size:12.2px;line-height:1.6;margin-top:18px}
.top{position:fixed;right:18px;bottom:18px;z-index:90;width:44px;height:44px;background:var(--merlot);color:#fff;display:flex;align-items:center;justify-content:center;text-decoration:none}
.top svg{width:18px;height:18px}
/* responsive */
@media (max-width:1240px){.nav>li>a,.drop-lbl{padding:10px 10px;font-size:13.2px}}
@media (max-width:1080px){
 .hero-in{grid-template-columns:1fr;min-height:0}
 .hero-txt{padding:clamp(38px,6vw,60px) var(--gut);max-width:none;order:2}
 .hero-img{order:1}.hero-img .ph-img{aspect-ratio:16/9;min-height:0}
 .band-in{grid-template-columns:1fr}.band-t{padding:clamp(42px,6vw,62px) var(--gut)}
 .band .ph-img{aspect-ratio:16/7;min-height:0}
 .quote-in{grid-template-columns:1fr}
 .strip-in{grid-template-columns:repeat(2,1fr);gap:24px}
 .g4,.g3{grid-template-columns:repeat(2,minmax(0,1fr))}
 .steps{grid-template-columns:repeat(2,minmax(0,1fr));gap:28px}
 .burg-lbl{display:block}.hdr-cta{display:none}
 .f-top{grid-template-columns:1.4fr 1fr 1fr;gap:28px}
 .nav{position:absolute;top:100%;left:0;right:0;flex-direction:column;align-items:stretch;background:var(--paper);border-bottom:1px solid var(--line);box-shadow:0 20px 40px rgba(32,32,31,.12);padding:8px var(--gut) 24px;max-height:0;overflow:hidden;visibility:hidden;transition:max-height .28s ease,visibility 0s .28s}
 .burger:checked ~ .nav{max-height:78vh;overflow-y:auto;visibility:visible;transition:max-height .3s ease,visibility 0s}
 .nav>li>a,.drop-lbl{padding:14px 2px;font-size:15.6px;border-bottom:1px solid #F1EAE0;justify-content:space-between}
 .menu{position:static;opacity:1;visibility:visible;transform:none;border:0;box-shadow:none;padding:0 0 6px 12px;min-width:0;max-height:0;overflow:hidden;background:transparent;transition:max-height .26s ease}
 .dtog:checked ~ .menu{max-height:760px}
 .dtog:checked ~ .drop-lbl .caret{transform:rotate(180deg)}
 .nav>li:hover>.menu,.nav>li:focus-within>.menu{opacity:1;visibility:visible}
 .mob-cta{display:block;margin-top:20px}
 .mob-cta .btn{width:100%;color:#fff;background:var(--merlot);border:1px solid var(--merlot);border-bottom:1px solid var(--merlot);justify-content:center;padding:16px 26px;font-size:12px}
 .mob-cta .btn:hover{background:var(--merlot-d);color:#fff}
}
@media (min-width:1081px){.mob-cta{display:none}}
@media (max-width:660px){
 .strip-in{grid-template-columns:1fr;gap:18px}
 .g2,.g3,.g4,.steps{grid-template-columns:1fr}
 .frow{grid-template-columns:1fr}
 .f-top{grid-template-columns:1fr;gap:28px}
 .work .ph-img{aspect-ratio:4/3}
}


:root{--pat:url('data:image/png;base64,')}

*{box-sizing:border-box}
svg{width:18px;height:18px;flex-shrink:0}
:root{
 /* Palette from the Aisle & Stem Integrated Visual Developer Guide */
 --porcelain:#F8F4ED; --merlot:#5A2B38; --taupe:#C8B9AA; --ink:#20201F;
 --merlot-d:#46212B; --merlot-l:#7A4353; --blush:#EFE3E4;
 --paper:#FFFFFF; --sand:#F2EBE1; --taupe-s:#EDE4D9; --soft:#6B6560; --line:#E3D9CC;
 --gut:clamp(18px,5vw,54px); --r:2px;
 --dsp:'EB Garamond',Georgia,'Times New Roman',serif;
 --bdy:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;
}
html{scroll-behavior:smooth}
body{margin:0;background:var(--porcelain);color:var(--ink);font:400 16px/1.72 var(--bdy);-webkit-font-smoothing:antialiased}
img{max-width:100%;display:block}
a{color:var(--merlot)}
.wrap{max-width:1280px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
h1,h2,h3{font-family:var(--dsp);font-weight:500;line-height:1.12;margin:0;letter-spacing:-.004em}
h1{font-size:clamp(34px,4.2vw,52px)}
h2{font-size:clamp(28px,3.6vw,44px)}
h3{font-size:clamp(19px,1.9vw,23px);line-height:1.3}
p{margin:0 0 16px}
.eyebrow{font:500 10.8px/1 var(--bdy);letter-spacing:.24em;text-transform:uppercase;color:var(--merlot);margin:0 0 16px;display:block}
.lede{font-size:clamp(16.5px,1.5vw,18.5px);color:#443F3B;line-height:1.7}
.sec{padding:clamp(56px,6.5vw,104px) 0}
.sec.alt{background-color:var(--paper)}
.sec.sand{background-color:var(--sand)}
.rv{animation:rvIn .85s both}
.rv2{animation-delay:.09s}.rv3{animation-delay:.18s}.rv4{animation-delay:.27s}
@keyframes rvIn{from{opacity:0;transform:translateY(22px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.rv{animation:none}}
.skip{position:absolute;left:-9999px;top:0;background:var(--merlot);color:#fff;padding:12px 18px;z-index:200}
.skip:focus{left:8px;top:8px}
a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible,label:focus-visible{outline:2.5px solid var(--merlot);outline-offset:3px}
.ph-img{width:100%;object-fit:cover;background:var(--taupe-s)}
/* interior pages */
.crumb{font:400 12.6px/1.6 var(--bdy);color:var(--soft);padding-top:20px}
.crumb a{color:var(--soft);text-decoration:none}
.crumb a:hover{color:var(--merlot)}
.crumb span{color:var(--taupe);margin:0 7px}
.crumb b{color:var(--ink);font-weight:500}
.sub{background-color:var(--porcelain);border-bottom:1px solid var(--line)}
.sub-in{display:grid;grid-template-columns:1.08fr .92fr;gap:clamp(28px,4vw,60px);align-items:center;
 padding-top:clamp(30px,3.6vw,52px);padding-bottom:clamp(40px,4.6vw,68px)}
.sub-in>*{min-width:0}
.sub h1{margin-bottom:20px}
.sub .ph-img{aspect-ratio:4/3}
.sub-solo{max-width:840px;padding-top:clamp(28px,3.4vw,46px);padding-bottom:clamp(40px,4.6vw,66px)}
.prose{max-width:820px}
.prose h2{margin-top:clamp(36px,4vw,58px);margin-bottom:14px}
.prose h2:first-child{margin-top:0}
.prose h3{margin-top:30px;margin-bottom:10px}
.prose p{font-size:16.4px;line-height:1.78;color:#443F3B}
.prose ul.b{list-style:none;margin:14px 0 20px;padding:0}
.prose ul.b li{position:relative;padding-left:24px;margin-bottom:10px;font-size:16px;line-height:1.72;color:#443F3B}
.prose ul.b li::before{content:"";position:absolute;left:2px;top:11px;width:7px;height:7px;border:1px solid var(--merlot);transform:rotate(45deg)}
.prose .tw{margin:20px 0 8px}
.note{background-color:var(--sand);border-left:2px solid var(--merlot);padding:18px 22px;margin:22px 0;font-size:15.4px;line-height:1.7;color:#443F3B}
.note b{color:var(--ink)}
.faq{max-width:820px;margin-top:clamp(30px,3.4vw,44px)}
.glist{display:grid;gap:16px}
.gl{display:grid;grid-template-columns:1fr 220px;gap:24px;align-items:center;background-color:var(--paper);border:1px solid var(--line);padding:clamp(22px,2.6vw,34px);text-decoration:none;transition:border-color .2s,transform .2s}
.gl:hover{border-color:var(--merlot);transform:translateY(-2px)}
.gl h3{font-family:var(--dsp);font-size:clamp(21px,2.1vw,26px);font-weight:500;color:var(--ink);margin:10px 0 8px;line-height:1.25}
.gl p{font-size:15px;color:var(--soft);line-height:1.65;margin:0 0 14px;max-width:62ch}
.gl .tag{display:inline-block;font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--merlot);font-weight:600}
.gl-r{font-size:13px;color:var(--soft);text-align:right;border-left:1px solid var(--line);padding-left:24px}
.gl-r b{display:block;color:var(--ink);font-weight:500;margin-top:4px}
@media (max-width:820px){.gl{grid-template-columns:1fr;gap:14px}.gl-r{text-align:left;border-left:0;border-top:1px solid var(--line);padding:14px 0 0}}
.prose p.upd{font-size:13px;color:var(--soft);border-left:2px solid var(--taupe);padding-left:14px;margin-top:26px;font-style:italic}
details{border-bottom:1px solid var(--line)}
summary{padding:18px 2px;cursor:pointer;font:500 16.4px/1.5 var(--bdy);color:var(--ink);list-style:none;display:flex;justify-content:space-between;gap:18px;align-items:flex-start}
summary::-webkit-details-marker{display:none}
summary::after{content:"";width:9px;height:9px;border-right:1.6px solid var(--merlot);border-bottom:1.6px solid var(--merlot);transform:rotate(45deg);flex-shrink:0;margin-top:7px;transition:.2s}
details[open] summary::after{transform:rotate(-135deg)}
details .a{padding:0 2px 20px;font-size:15.6px;color:#443F3B;line-height:1.76;max-width:74ch}
details .a p:last-child{margin-bottom:0}
.side{background-color:var(--paper);border:1px solid var(--line);padding:24px 26px;position:sticky;top:96px}
.side h3{font-size:20px;margin-bottom:12px}
.side ul{list-style:none;margin:0;padding:0}
.side li{border-bottom:1px solid #F1EAE0}
.side li:last-child{border-bottom:0}
.side a{display:block;padding:11px 0;font-size:14.8px;color:#443F3B;text-decoration:none}
.side a:hover{color:var(--merlot)}
.split{display:grid;grid-template-columns:1fr 320px;gap:clamp(30px,4vw,56px);align-items:start}
.split>*{min-width:0}
@media (max-width:1080px){.sub-in{grid-template-columns:1fr}.sub .shot{order:-1}.split{grid-template-columns:1fr}
.side{position:static;top:auto}}
/* botanical watermark, opacity baked into the PNG so no pseudo-element or z-index is needed */
.wm{background-image:var(--pat);background-repeat:repeat;background-size:440px 440px;background-position:center top}
@media (max-width:700px){.wm{background-size:300px 300px}}

/* header */
header{position:sticky;top:0;z-index:120;background:rgba(248,244,237,.95);backdrop-filter:saturate(1.3) blur(10px);border-bottom:1px solid var(--line)}
.hdr-in{max-width:1280px;margin:0 auto;padding:0 var(--gut);display:flex;align-items:center;gap:18px;min-height:94px}
.brand{display:flex;align-items:center;flex-shrink:0;margin-right:auto}
.brand img{height:50px;width:auto}
.nav{display:flex;align-items:center;gap:0;list-style:none;margin:0;padding:0}
.nav>li{position:relative}
.nav>li>a,.drop-lbl{display:flex;align-items:center;gap:5px;padding:10px 13px;font:400 13.8px/1 var(--bdy);letter-spacing:.02em;color:var(--ink);text-decoration:none;cursor:pointer;white-space:nowrap}
.nav>li>a:hover,.drop-lbl:hover{color:var(--merlot)}
.caret{width:10px;height:10px;transition:transform .2s;opacity:.55}
.menu{position:absolute;top:calc(100% + 6px);left:0;min-width:272px;background:var(--paper);border:1px solid var(--line);padding:8px;box-shadow:0 22px 50px rgba(32,32,31,.13);list-style:none;margin:0;opacity:0;visibility:hidden;transform:translateY(-6px);transition:.16s}
.nav>li:hover>.menu,.nav>li:focus-within>.menu{opacity:1;visibility:visible;transform:none}
.menu a{display:block;padding:9px 13px;font:400 13.9px/1.45 var(--bdy);color:#443F3B;text-decoration:none}
.menu a:hover{background:var(--sand);color:var(--merlot)}
.menu .grp{padding:11px 13px 4px;font:500 10px/1 var(--bdy);letter-spacing:.18em;text-transform:uppercase;color:var(--soft)}
.hdr-cta{flex-shrink:0;margin-left:10px}
.burger,.dtog{position:absolute;opacity:0;pointer-events:none;width:0;height:0}
.burg-lbl{display:none;cursor:pointer;padding:10px;margin-left:auto;border:1px solid var(--line);background:var(--paper)}
.burg-lbl svg{width:22px;height:22px}
/* buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;padding:15px 30px;font:500 12.4px/1 var(--bdy);letter-spacing:.13em;text-transform:uppercase;text-decoration:none;border:1px solid transparent;cursor:pointer;transition:.18s;text-align:center}
.btn-p{background:var(--merlot);color:#fff}
.btn-p:hover{background:var(--merlot-d)}
.btn-s{background:transparent;color:var(--ink);border-color:var(--ink)}
.btn-s:hover{background:var(--ink);color:#fff}
.btn-w{background:transparent;color:#fff;border-color:rgba(255,255,255,.55)}
.btn-w:hover{background:#fff;color:var(--merlot)}
.btn-sm{padding:12px 22px;font-size:11.4px}
/* hero */
.hero{position:relative;background-color:var(--porcelain)}
.hero-in{display:grid;grid-template-columns:1.02fr .98fr;gap:0;align-items:stretch;min-height:min(76vh,660px)}
.hero-in>*{min-width:0}
.hero-txt{padding:clamp(44px,5.5vw,84px) clamp(24px,4vw,64px) clamp(44px,5.5vw,84px) var(--gut);display:flex;flex-direction:column;justify-content:center;max-width:760px;margin-left:auto;width:100%}
.hero h1{margin-bottom:22px}
.ans{border-left:2px solid var(--merlot);padding:4px 0 4px 20px;margin:0 0 30px;font-size:16.6px;line-height:1.72;color:#443F3B}
.hero-cta{display:flex;flex-wrap:wrap;gap:12px;margin-bottom:24px}
.hero-note{font-size:13.2px;color:var(--soft);display:flex;align-items:center;gap:9px;margin:0}
.hero-note svg{width:15px;height:15px;color:var(--merlot)}
.hero-img{position:relative}
.hero-img .ph-img{height:100%;min-height:340px}
/* strip */
.strip{background-color:var(--ink);color:#E8E3DC}
.strip-in{display:grid;grid-template-columns:repeat(4,1fr);gap:28px;padding-top:32px;padding-bottom:32px}
.strip-in>div{min-width:0}
.strip b{display:block;font-family:var(--dsp);font-size:23px;font-weight:500;color:#fff;line-height:1.25;margin-bottom:4px}
.strip span{font-size:12.9px;color:#B3ACA3;line-height:1.55;display:block}
/* layout */
.head{max-width:790px;margin-bottom:clamp(30px,3.6vw,52px)}
.head.mid{margin-left:auto;margin-right:auto;text-align:center}
.grid{display:grid;gap:clamp(16px,1.8vw,26px)}
.grid>*{min-width:0}
.g2{grid-template-columns:repeat(2,minmax(0,1fr))}
.g3{grid-template-columns:repeat(3,minmax(0,1fr))}
.g4{grid-template-columns:repeat(4,minmax(0,1fr))}
/* photo cards */
.pc{background:var(--paper);border:1px solid var(--line);display:flex;flex-direction:column;text-decoration:none;color:inherit;transition:.2s}
.pc:hover{border-color:var(--taupe);box-shadow:0 16px 40px rgba(32,32,31,.08);transform:translateY(-3px)}
.pc .ph-img{aspect-ratio:4/3}
.pc-b{padding:22px 24px 24px;display:flex;flex-direction:column;flex:1}
.pc-b h2,.pc-b h3{font-size:clamp(20px,2vw,25px);margin-bottom:9px}
.pc-b p{font-size:14.8px;color:#4E4842;margin-bottom:16px;line-height:1.66}
.go{margin-top:auto;font:500 11.4px/1 var(--bdy);letter-spacing:.14em;text-transform:uppercase;color:var(--merlot);text-decoration:none;display:inline-flex;align-items:center;gap:8px}
.go svg{width:13px;height:13px;transition:.2s}
.pc:hover .go svg,.go:hover svg{transform:translateX(4px)}
.pc-kicker{font:500 10.2px/1 var(--bdy);letter-spacing:.2em;text-transform:uppercase;color:var(--soft);margin-bottom:9px;display:block}
/* work grid */
.work .ph-img{aspect-ratio:3/3.6}
.work .cap{padding:14px 2px 0}
.work .cap b{display:block;font-family:var(--dsp);font-size:19px;font-weight:500;margin-bottom:2px}
.work .cap span{font-size:12.6px;color:var(--soft)}
/* table */
.tw{overflow-x:auto;border:1px solid var(--line);background:var(--paper)}
table{width:100%;border-collapse:collapse;font-size:14.8px;min-width:580px}
th{text-align:left;padding:15px 20px;background:var(--sand);font:500 10.6px/1.3 var(--bdy);letter-spacing:.15em;text-transform:uppercase;color:var(--soft);border-bottom:1px solid var(--line)}
td{padding:15px 20px;border-bottom:1px solid #F0E9DF;color:#4E4842;vertical-align:top}
tr:last-child td{border-bottom:0}
td b{color:var(--ink);font-weight:600}
/* steps */
.steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:clamp(18px,2.4vw,36px);counter-reset:s}
.step{min-width:0}
.step-n{counter-increment:s;font-family:var(--dsp);font-size:15px;color:var(--merlot);letter-spacing:.14em;margin-bottom:14px;display:block;padding-bottom:12px;border-bottom:1px solid var(--taupe)}
.step-n::before{content:"0" counter(s)}
.step h3{margin-bottom:7px;font-size:21px}
.step p{margin:0;font-size:14.8px;color:#4E4842;line-height:1.68}
/* cta strip */
.band{background-color:var(--merlot);color:#fff;position:relative;overflow:hidden}
.band-in{display:grid;grid-template-columns:1.25fr .75fr;gap:0;align-items:stretch}
.band-in>*{min-width:0}
.band-t{padding:clamp(46px,5.5vw,80px) clamp(28px,4vw,56px) clamp(46px,5.5vw,80px) var(--gut);display:flex;flex-direction:column;justify-content:center}
.band h2{color:#fff;font-size:clamp(28px,3.4vw,42px);margin-bottom:12px;max-width:16ch}
.band p{color:#E2CFD4;margin:0 0 26px;font-size:16px;max-width:46ch}
.band .ph-img{height:100%;min-height:240px}
/* enquiry */
.quote-in{display:grid;grid-template-columns:.9fr 1.1fr;gap:clamp(30px,4.5vw,62px);align-items:center}
.quote-in>*{min-width:0}
.qlist{list-style:none;margin:26px 0 0;padding:0}
.qlist li{display:flex;gap:12px;align-items:flex-start;margin-bottom:13px;font-size:15.2px;color:#4E4842}
.qlist svg{width:16px;height:16px;color:var(--merlot);margin-top:4px}
.fbox{background:var(--paper);border:1px solid var(--line);padding:clamp(24px,3vw,38px)}
.fbox-t{font-family:var(--dsp);font-size:clamp(22px,2.2vw,28px);font-weight:500;line-height:1.24;margin:0 0 6px}
.fbox .sm{font-size:13.4px;color:var(--soft);margin-bottom:22px}
.frow{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}
.frow>*{min-width:0}
.field{margin-bottom:15px;min-width:0}
.field label{display:block;font:500 11.4px/1 var(--bdy);letter-spacing:.1em;text-transform:uppercase;color:var(--soft);margin-bottom:8px}
.req{color:var(--merlot)}
input,select,textarea{width:100%;min-width:0;padding:13px 15px;border:1px solid var(--line);font:400 15px/1.45 var(--bdy);color:var(--ink);background:var(--paper);border-radius:0}
textarea{min-height:106px;resize:vertical}
select option{background:#fff;color:var(--ink)}
input:hover,select:hover,textarea:hover{border-color:var(--taupe)}
input:focus,select:focus,textarea:focus{border-color:var(--merlot)}
.fnote{font-size:12.4px;color:var(--soft);margin:15px 0 0;line-height:1.6}
/* footer */
footer{background-color:var(--ink);color:#B3ACA3;padding-top:clamp(48px,6vw,76px);padding-bottom:30px}
.f-top{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr 1fr;gap:34px;padding-bottom:42px;border-bottom:1px solid rgba(255,255,255,.1)}
.f-top>*{min-width:0}
.f-brand img{height:54px;width:auto;margin-bottom:22px}
.f-desc{font-size:14.2px;color:#C0B9AF;line-height:1.72;max-width:330px}
.f-tag{font-family:var(--dsp);font-size:20px;color:#fff;margin:16px 0 0;line-height:1.4}
footer h4{font:500 10.4px/1 var(--bdy);letter-spacing:.18em;text-transform:uppercase;color:#fff;margin:0 0 16px}
footer ul{list-style:none;margin:0;padding:0}
footer li{margin-bottom:10px}
footer a{color:#B3ACA3;text-decoration:none;font-size:14px;line-height:1.5}
footer a:hover{color:#fff}
.f-bot{display:flex;flex-wrap:wrap;gap:14px;justify-content:space-between;align-items:center;padding-top:26px;font-size:12.8px;color:#8A837B}
.built{display:inline-flex;align-items:center;gap:9px}
.built-ico{width:22px;height:22px}
.built b{color:var(--taupe);font-weight:600}
.pend{background:rgba(200,185,170,.13);border:1px solid rgba(200,185,170,.3);color:#D6CEC3;padding:11px 14px;font-size:12.2px;line-height:1.6;margin-top:18px}
.top{position:fixed;right:18px;bottom:18px;z-index:90;width:44px;height:44px;background:var(--merlot);color:#fff;display:flex;align-items:center;justify-content:center;text-decoration:none}
.top svg{width:18px;height:18px}
/* responsive */
@media (max-width:1240px){.nav>li>a,.drop-lbl{padding:10px 10px;font-size:13.2px}}
@media (max-width:1080px){
 .hero-in{grid-template-columns:1fr;min-height:0}
 .hero-txt{padding:clamp(38px,6vw,60px) var(--gut);max-width:none;order:2}
 .hero-img{order:1}.hero-img .ph-img{aspect-ratio:16/9;min-height:0}
 .band-in{grid-template-columns:1fr}.band-t{padding:clamp(42px,6vw,62px) var(--gut)}
 .band .ph-img{aspect-ratio:16/7;min-height:0}
 .quote-in{grid-template-columns:1fr}
 .strip-in{grid-template-columns:repeat(2,1fr);gap:24px}
 .g4,.g3{grid-template-columns:repeat(2,minmax(0,1fr))}
 .steps{grid-template-columns:repeat(2,minmax(0,1fr));gap:28px}
 .burg-lbl{display:block}.hdr-cta{display:none}
 .f-top{grid-template-columns:1.4fr 1fr 1fr;gap:28px}
 .nav{position:absolute;top:100%;left:0;right:0;flex-direction:column;align-items:stretch;background:var(--paper);border-bottom:1px solid var(--line);box-shadow:0 20px 40px rgba(32,32,31,.12);padding:8px var(--gut) 24px;max-height:0;overflow:hidden;visibility:hidden;transition:max-height .28s ease,visibility 0s .28s}
 .burger:checked ~ .nav{max-height:78vh;overflow-y:auto;visibility:visible;transition:max-height .3s ease,visibility 0s}
 .nav>li>a,.drop-lbl{padding:14px 2px;font-size:15.6px;border-bottom:1px solid #F1EAE0;justify-content:space-between}
 .menu{position:static;opacity:1;visibility:visible;transform:none;border:0;box-shadow:none;padding:0 0 6px 12px;min-width:0;max-height:0;overflow:hidden;background:transparent;transition:max-height .26s ease}
 .dtog:checked ~ .menu{max-height:760px}
 .dtog:checked ~ .drop-lbl .caret{transform:rotate(180deg)}
 .nav>li:hover>.menu,.nav>li:focus-within>.menu{opacity:1;visibility:visible}
 .mob-cta{display:block;margin-top:20px}
 .mob-cta .btn{width:100%;color:#fff;background:var(--merlot);border:1px solid var(--merlot);border-bottom:1px solid var(--merlot);justify-content:center;padding:16px 26px;font-size:12px}
 .mob-cta .btn:hover{background:var(--merlot-d);color:#fff}
}
@media (min-width:1081px){.mob-cta{display:none}}
@media (max-width:660px){
 .strip-in{grid-template-columns:1fr;gap:18px}
 .g2,.g3,.g4,.steps{grid-template-columns:1fr}
 .frow{grid-template-columns:1fr}
 .f-top{grid-template-columns:1fr;gap:28px}
 .work .ph-img{aspect-ratio:4/3}
}


:root{--pat:url('data:image/png;base64,')}

*{box-sizing:border-box}
svg{width:18px;height:18px;flex-shrink:0}
:root{
 /* Palette from the Aisle & Stem Integrated Visual Developer Guide */
 --porcelain:#F8F4ED; --merlot:#5A2B38; --taupe:#C8B9AA; --ink:#20201F;
 --merlot-d:#46212B; --merlot-l:#7A4353; --blush:#EFE3E4;
 --paper:#FFFFFF; --sand:#F2EBE1; --taupe-s:#EDE4D9; --soft:#6B6560; --line:#E3D9CC;
 --gut:clamp(18px,5vw,54px); --r:2px;
 --dsp:'EB Garamond',Georgia,'Times New Roman',serif;
 --bdy:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;
}
html{scroll-behavior:smooth}
body{margin:0;background:var(--porcelain);color:var(--ink);font:400 16px/1.72 var(--bdy);-webkit-font-smoothing:antialiased}
img{max-width:100%;display:block}
a{color:var(--merlot)}
.wrap{max-width:1280px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
h1,h2,h3{font-family:var(--dsp);font-weight:500;line-height:1.12;margin:0;letter-spacing:-.004em}
h1{font-size:clamp(34px,4.2vw,52px)}
h2{font-size:clamp(28px,3.6vw,44px)}
h3{font-size:clamp(19px,1.9vw,23px);line-height:1.3}
p{margin:0 0 16px}
.eyebrow{font:500 10.8px/1 var(--bdy);letter-spacing:.24em;text-transform:uppercase;color:var(--merlot);margin:0 0 16px;display:block}
.lede{font-size:clamp(16.5px,1.5vw,18.5px);color:#443F3B;line-height:1.7}
.sec{padding:clamp(56px,6.5vw,104px) 0}
.sec.alt{background-color:var(--paper)}
.sec.sand{background-color:var(--sand)}
.rv{animation:rvIn .85s both}
.rv2{animation-delay:.09s}.rv3{animation-delay:.18s}.rv4{animation-delay:.27s}
@keyframes rvIn{from{opacity:0;transform:translateY(22px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.rv{animation:none}}
.skip{position:absolute;left:-9999px;top:0;background:var(--merlot);color:#fff;padding:12px 18px;z-index:200}
.skip:focus{left:8px;top:8px}
a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible,label:focus-visible{outline:2.5px solid var(--merlot);outline-offset:3px}
.ph-img{width:100%;object-fit:cover;background:var(--taupe-s)}
/* interior pages */
.crumb{font:400 12.6px/1.6 var(--bdy);color:var(--soft);padding-top:20px}
.crumb a{color:var(--soft);text-decoration:none}
.crumb a:hover{color:var(--merlot)}
.crumb span{color:var(--taupe);margin:0 7px}
.crumb b{color:var(--ink);font-weight:500}
.sub{background-color:var(--porcelain);border-bottom:1px solid var(--line)}
.sub-in{display:grid;grid-template-columns:1.08fr .92fr;gap:clamp(28px,4vw,60px);align-items:center;
 padding-top:clamp(30px,3.6vw,52px);padding-bottom:clamp(40px,4.6vw,68px)}
.sub-in>*{min-width:0}
.sub h1{margin-bottom:20px}
.sub .ph-img{aspect-ratio:4/3}
.sub-solo{max-width:840px;padding-top:clamp(28px,3.4vw,46px);padding-bottom:clamp(40px,4.6vw,66px)}
.prose{max-width:820px}
.prose h2{margin-top:clamp(36px,4vw,58px);margin-bottom:14px}
.prose h2:first-child{margin-top:0}
.prose h3{margin-top:30px;margin-bottom:10px}
.prose p{font-size:16.4px;line-height:1.78;color:#443F3B}
.prose ul.b{list-style:none;margin:14px 0 20px;padding:0}
.prose ul.b li{position:relative;padding-left:24px;margin-bottom:10px;font-size:16px;line-height:1.72;color:#443F3B}
.prose ul.b li::before{content:"";position:absolute;left:2px;top:11px;width:7px;height:7px;border:1px solid var(--merlot);transform:rotate(45deg)}
.prose .tw{margin:20px 0 8px}
.note{background-color:var(--sand);border-left:2px solid var(--merlot);padding:18px 22px;margin:22px 0;font-size:15.4px;line-height:1.7;color:#443F3B}
.note b{color:var(--ink)}
.faq{max-width:820px;margin-top:clamp(30px,3.4vw,44px)}
.glist{display:grid;gap:16px}
.gl{display:grid;grid-template-columns:1fr 220px;gap:24px;align-items:center;background-color:var(--paper);border:1px solid var(--line);padding:clamp(22px,2.6vw,34px);text-decoration:none;transition:border-color .2s,transform .2s}
.gl:hover{border-color:var(--merlot);transform:translateY(-2px)}
.gl h3{font-family:var(--dsp);font-size:clamp(21px,2.1vw,26px);font-weight:500;color:var(--ink);margin:10px 0 8px;line-height:1.25}
.gl p{font-size:15px;color:var(--soft);line-height:1.65;margin:0 0 14px;max-width:62ch}
.gl .tag{display:inline-block;font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--merlot);font-weight:600}
.gl-r{font-size:13px;color:var(--soft);text-align:right;border-left:1px solid var(--line);padding-left:24px}
.gl-r b{display:block;color:var(--ink);font-weight:500;margin-top:4px}
@media (max-width:820px){.gl{grid-template-columns:1fr;gap:14px}.gl-r{text-align:left;border-left:0;border-top:1px solid var(--line);padding:14px 0 0}}
.prose p.upd{font-size:13px;color:var(--soft);border-left:2px solid var(--taupe);padding-left:14px;margin-top:26px;font-style:italic}
details{border-bottom:1px solid var(--line)}
summary{padding:18px 2px;cursor:pointer;font:500 16.4px/1.5 var(--bdy);color:var(--ink);list-style:none;display:flex;justify-content:space-between;gap:18px;align-items:flex-start}
summary::-webkit-details-marker{display:none}
summary::after{content:"";width:9px;height:9px;border-right:1.6px solid var(--merlot);border-bottom:1.6px solid var(--merlot);transform:rotate(45deg);flex-shrink:0;margin-top:7px;transition:.2s}
details[open] summary::after{transform:rotate(-135deg)}
details .a{padding:0 2px 20px;font-size:15.6px;color:#443F3B;line-height:1.76;max-width:74ch}
details .a p:last-child{margin-bottom:0}
.side{background-color:var(--paper);border:1px solid var(--line);padding:24px 26px;position:sticky;top:96px}
.side h3{font-size:20px;margin-bottom:12px}
.side ul{list-style:none;margin:0;padding:0}
.side li{border-bottom:1px solid #F1EAE0}
.side li:last-child{border-bottom:0}
.side a{display:block;padding:11px 0;font-size:14.8px;color:#443F3B;text-decoration:none}
.side a:hover{color:var(--merlot)}
.split{display:grid;grid-template-columns:1fr 320px;gap:clamp(30px,4vw,56px);align-items:start}
.split>*{min-width:0}
@media (max-width:1080px){.sub-in{grid-template-columns:1fr}.sub .shot{order:-1}.split{grid-template-columns:1fr}
.side{position:static;top:auto}}
/* botanical watermark, opacity baked into the PNG so no pseudo-element or z-index is needed */
.wm{background-image:var(--pat);background-repeat:repeat;background-size:440px 440px;background-position:center top}
@media (max-width:700px){.wm{background-size:300px 300px}}

/* header */
header{position:sticky;top:0;z-index:120;background:rgba(248,244,237,.95);backdrop-filter:saturate(1.3) blur(10px);border-bottom:1px solid var(--line)}
.hdr-in{max-width:1280px;margin:0 auto;padding:0 var(--gut);display:flex;align-items:center;gap:18px;min-height:94px}
.brand{display:flex;align-items:center;flex-shrink:0;margin-right:auto}
.brand img{height:50px;width:auto}
.nav{display:flex;align-items:center;gap:0;list-style:none;margin:0;padding:0}
.nav>li{position:relative}
.nav>li>a,.drop-lbl{display:flex;align-items:center;gap:5px;padding:10px 13px;font:400 13.8px/1 var(--bdy);letter-spacing:.02em;color:var(--ink);text-decoration:none;cursor:pointer;white-space:nowrap}
.nav>li>a:hover,.drop-lbl:hover{color:var(--merlot)}
.caret{width:10px;height:10px;transition:transform .2s;opacity:.55}
.menu{position:absolute;top:calc(100% + 6px);left:0;min-width:272px;background:var(--paper);border:1px solid var(--line);padding:8px;box-shadow:0 22px 50px rgba(32,32,31,.13);list-style:none;margin:0;opacity:0;visibility:hidden;transform:translateY(-6px);transition:.16s}
.nav>li:hover>.menu,.nav>li:focus-within>.menu{opacity:1;visibility:visible;transform:none}
.menu a{display:block;padding:9px 13px;font:400 13.9px/1.45 var(--bdy);color:#443F3B;text-decoration:none}
.menu a:hover{background:var(--sand);color:var(--merlot)}
.menu .grp{padding:11px 13px 4px;font:500 10px/1 var(--bdy);letter-spacing:.18em;text-transform:uppercase;color:var(--soft)}
.hdr-cta{flex-shrink:0;margin-left:10px}
.burger,.dtog{position:absolute;opacity:0;pointer-events:none;width:0;height:0}
.burg-lbl{display:none;cursor:pointer;padding:10px;margin-left:auto;border:1px solid var(--line);background:var(--paper)}
.burg-lbl svg{width:22px;height:22px}
/* buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;padding:15px 30px;font:500 12.4px/1 var(--bdy);letter-spacing:.13em;text-transform:uppercase;text-decoration:none;border:1px solid transparent;cursor:pointer;transition:.18s;text-align:center}
.btn-p{background:var(--merlot);color:#fff}
.btn-p:hover{background:var(--merlot-d)}
.btn-s{background:transparent;color:var(--ink);border-color:var(--ink)}
.btn-s:hover{background:var(--ink);color:#fff}
.btn-w{background:transparent;color:#fff;border-color:rgba(255,255,255,.55)}
.btn-w:hover{background:#fff;color:var(--merlot)}
.btn-sm{padding:12px 22px;font-size:11.4px}
/* hero */
.hero{position:relative;background-color:var(--porcelain)}
.hero-in{display:grid;grid-template-columns:1.02fr .98fr;gap:0;align-items:stretch;min-height:min(76vh,660px)}
.hero-in>*{min-width:0}
.hero-txt{padding:clamp(44px,5.5vw,84px) clamp(24px,4vw,64px) clamp(44px,5.5vw,84px) var(--gut);display:flex;flex-direction:column;justify-content:center;max-width:760px;margin-left:auto;width:100%}
.hero h1{margin-bottom:22px}
.ans{border-left:2px solid var(--merlot);padding:4px 0 4px 20px;margin:0 0 30px;font-size:16.6px;line-height:1.72;color:#443F3B}
.hero-cta{display:flex;flex-wrap:wrap;gap:12px;margin-bottom:24px}
.hero-note{font-size:13.2px;color:var(--soft);display:flex;align-items:center;gap:9px;margin:0}
.hero-note svg{width:15px;height:15px;color:var(--merlot)}
.hero-img{position:relative}
.hero-img .ph-img{height:100%;min-height:340px}
/* strip */
.strip{background-color:var(--ink);color:#E8E3DC}
.strip-in{display:grid;grid-template-columns:repeat(4,1fr);gap:28px;padding-top:32px;padding-bottom:32px}
.strip-in>div{min-width:0}
.strip b{display:block;font-family:var(--dsp);font-size:23px;font-weight:500;color:#fff;line-height:1.25;margin-bottom:4px}
.strip span{font-size:12.9px;color:#B3ACA3;line-height:1.55;display:block}
/* layout */
.head{max-width:790px;margin-bottom:clamp(30px,3.6vw,52px)}
.head.mid{margin-left:auto;margin-right:auto;text-align:center}
.grid{display:grid;gap:clamp(16px,1.8vw,26px)}
.grid>*{min-width:0}
.g2{grid-template-columns:repeat(2,minmax(0,1fr))}
.g3{grid-template-columns:repeat(3,minmax(0,1fr))}
.g4{grid-template-columns:repeat(4,minmax(0,1fr))}
/* photo cards */
.pc{background:var(--paper);border:1px solid var(--line);display:flex;flex-direction:column;text-decoration:none;color:inherit;transition:.2s}
.pc:hover{border-color:var(--taupe);box-shadow:0 16px 40px rgba(32,32,31,.08);transform:translateY(-3px)}
.pc .ph-img{aspect-ratio:4/3}
.pc-b{padding:22px 24px 24px;display:flex;flex-direction:column;flex:1}
.pc-b h2,.pc-b h3{font-size:clamp(20px,2vw,25px);margin-bottom:9px}
.pc-b p{font-size:14.8px;color:#4E4842;margin-bottom:16px;line-height:1.66}
.go{margin-top:auto;font:500 11.4px/1 var(--bdy);letter-spacing:.14em;text-transform:uppercase;color:var(--merlot);text-decoration:none;display:inline-flex;align-items:center;gap:8px}
.go svg{width:13px;height:13px;transition:.2s}
.pc:hover .go svg,.go:hover svg{transform:translateX(4px)}
.pc-kicker{font:500 10.2px/1 var(--bdy);letter-spacing:.2em;text-transform:uppercase;color:var(--soft);margin-bottom:9px;display:block}
/* work grid */
.work .ph-img{aspect-ratio:3/3.6}
.work .cap{padding:14px 2px 0}
.work .cap b{display:block;font-family:var(--dsp);font-size:19px;font-weight:500;margin-bottom:2px}
.work .cap span{font-size:12.6px;color:var(--soft)}
/* table */
.tw{overflow-x:auto;border:1px solid var(--line);background:var(--paper)}
table{width:100%;border-collapse:collapse;font-size:14.8px;min-width:580px}
th{text-align:left;padding:15px 20px;background:var(--sand);font:500 10.6px/1.3 var(--bdy);letter-spacing:.15em;text-transform:uppercase;color:var(--soft);border-bottom:1px solid var(--line)}
td{padding:15px 20px;border-bottom:1px solid #F0E9DF;color:#4E4842;vertical-align:top}
tr:last-child td{border-bottom:0}
td b{color:var(--ink);font-weight:600}
/* steps */
.steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:clamp(18px,2.4vw,36px);counter-reset:s}
.step{min-width:0}
.step-n{counter-increment:s;font-family:var(--dsp);font-size:15px;color:var(--merlot);letter-spacing:.14em;margin-bottom:14px;display:block;padding-bottom:12px;border-bottom:1px solid var(--taupe)}
.step-n::before{content:"0" counter(s)}
.step h3{margin-bottom:7px;font-size:21px}
.step p{margin:0;font-size:14.8px;color:#4E4842;line-height:1.68}
/* cta strip */
.band{background-color:var(--merlot);color:#fff;position:relative;overflow:hidden}
.band-in{display:grid;grid-template-columns:1.25fr .75fr;gap:0;align-items:stretch}
.band-in>*{min-width:0}
.band-t{padding:clamp(46px,5.5vw,80px) clamp(28px,4vw,56px) clamp(46px,5.5vw,80px) var(--gut);display:flex;flex-direction:column;justify-content:center}
.band h2{color:#fff;font-size:clamp(28px,3.4vw,42px);margin-bottom:12px;max-width:16ch}
.band p{color:#E2CFD4;margin:0 0 26px;font-size:16px;max-width:46ch}
.band .ph-img{height:100%;min-height:240px}
/* enquiry */
.quote-in{display:grid;grid-template-columns:.9fr 1.1fr;gap:clamp(30px,4.5vw,62px);align-items:center}
.quote-in>*{min-width:0}
.qlist{list-style:none;margin:26px 0 0;padding:0}
.qlist li{display:flex;gap:12px;align-items:flex-start;margin-bottom:13px;font-size:15.2px;color:#4E4842}
.qlist svg{width:16px;height:16px;color:var(--merlot);margin-top:4px}
.fbox{background:var(--paper);border:1px solid var(--line);padding:clamp(24px,3vw,38px)}
.fbox-t{font-family:var(--dsp);font-size:clamp(22px,2.2vw,28px);font-weight:500;line-height:1.24;margin:0 0 6px}
.fbox .sm{font-size:13.4px;color:var(--soft);margin-bottom:22px}
.frow{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}
.frow>*{min-width:0}
.field{margin-bottom:15px;min-width:0}
.field label{display:block;font:500 11.4px/1 var(--bdy);letter-spacing:.1em;text-transform:uppercase;color:var(--soft);margin-bottom:8px}
.req{color:var(--merlot)}
input,select,textarea{width:100%;min-width:0;padding:13px 15px;border:1px solid var(--line);font:400 15px/1.45 var(--bdy);color:var(--ink);background:var(--paper);border-radius:0}
textarea{min-height:106px;resize:vertical}
select option{background:#fff;color:var(--ink)}
input:hover,select:hover,textarea:hover{border-color:var(--taupe)}
input:focus,select:focus,textarea:focus{border-color:var(--merlot)}
.fnote{font-size:12.4px;color:var(--soft);margin:15px 0 0;line-height:1.6}
/* footer */
footer{background-color:var(--ink);color:#B3ACA3;padding-top:clamp(48px,6vw,76px);padding-bottom:30px}
.f-top{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr 1fr;gap:34px;padding-bottom:42px;border-bottom:1px solid rgba(255,255,255,.1)}
.f-top>*{min-width:0}
.f-brand img{height:54px;width:auto;margin-bottom:22px}
.f-desc{font-size:14.2px;color:#C0B9AF;line-height:1.72;max-width:330px}
.f-tag{font-family:var(--dsp);font-size:20px;color:#fff;margin:16px 0 0;line-height:1.4}
footer h4{font:500 10.4px/1 var(--bdy);letter-spacing:.18em;text-transform:uppercase;color:#fff;margin:0 0 16px}
footer ul{list-style:none;margin:0;padding:0}
footer li{margin-bottom:10px}
footer a{color:#B3ACA3;text-decoration:none;font-size:14px;line-height:1.5}
footer a:hover{color:#fff}
.f-bot{display:flex;flex-wrap:wrap;gap:14px;justify-content:space-between;align-items:center;padding-top:26px;font-size:12.8px;color:#8A837B}
.built{display:inline-flex;align-items:center;gap:9px}
.built-ico{width:22px;height:22px}
.built b{color:var(--taupe);font-weight:600}
.pend{background:rgba(200,185,170,.13);border:1px solid rgba(200,185,170,.3);color:#D6CEC3;padding:11px 14px;font-size:12.2px;line-height:1.6;margin-top:18px}
.top{position:fixed;right:18px;bottom:18px;z-index:90;width:44px;height:44px;background:var(--merlot);color:#fff;display:flex;align-items:center;justify-content:center;text-decoration:none}
.top svg{width:18px;height:18px}
/* responsive */
@media (max-width:1240px){.nav>li>a,.drop-lbl{padding:10px 10px;font-size:13.2px}}
@media (max-width:1080px){
 .hero-in{grid-template-columns:1fr;min-height:0}
 .hero-txt{padding:clamp(38px,6vw,60px) var(--gut);max-width:none;order:2}
 .hero-img{order:1}.hero-img .ph-img{aspect-ratio:16/9;min-height:0}
 .band-in{grid-template-columns:1fr}.band-t{padding:clamp(42px,6vw,62px) var(--gut)}
 .band .ph-img{aspect-ratio:16/7;min-height:0}
 .quote-in{grid-template-columns:1fr}
 .strip-in{grid-template-columns:repeat(2,1fr);gap:24px}
 .g4,.g3{grid-template-columns:repeat(2,minmax(0,1fr))}
 .steps{grid-template-columns:repeat(2,minmax(0,1fr));gap:28px}
 .burg-lbl{display:block}.hdr-cta{display:none}
 .f-top{grid-template-columns:1.4fr 1fr 1fr;gap:28px}
 .nav{position:absolute;top:100%;left:0;right:0;flex-direction:column;align-items:stretch;background:var(--paper);border-bottom:1px solid var(--line);box-shadow:0 20px 40px rgba(32,32,31,.12);padding:8px var(--gut) 24px;max-height:0;overflow:hidden;visibility:hidden;transition:max-height .28s ease,visibility 0s .28s}
 .burger:checked ~ .nav{max-height:78vh;overflow-y:auto;visibility:visible;transition:max-height .3s ease,visibility 0s}
 .nav>li>a,.drop-lbl{padding:14px 2px;font-size:15.6px;border-bottom:1px solid #F1EAE0;justify-content:space-between}
 .menu{position:static;opacity:1;visibility:visible;transform:none;border:0;box-shadow:none;padding:0 0 6px 12px;min-width:0;max-height:0;overflow:hidden;background:transparent;transition:max-height .26s ease}
 .dtog:checked ~ .menu{max-height:760px}
 .dtog:checked ~ .drop-lbl .caret{transform:rotate(180deg)}
 .nav>li:hover>.menu,.nav>li:focus-within>.menu{opacity:1;visibility:visible}
 .mob-cta{display:block;margin-top:20px}
 .mob-cta .btn{width:100%;color:#fff;background:var(--merlot);border:1px solid var(--merlot);border-bottom:1px solid var(--merlot);justify-content:center;padding:16px 26px;font-size:12px}
 .mob-cta .btn:hover{background:var(--merlot-d);color:#fff}
}
@media (min-width:1081px){.mob-cta{display:none}}
@media (max-width:660px){
 .strip-in{grid-template-columns:1fr;gap:18px}
 .g2,.g3,.g4,.steps{grid-template-columns:1fr}
 .frow{grid-template-columns:1fr}
 .f-top{grid-template-columns:1fr;gap:28px}
 .work .ph-img{aspect-ratio:4/3}
}


:root{--pat:url('data:image/png;base64,')}
